COLLDATA("tadabburar","ar",[[571,"§نوح\nwords\nمِدرَارًامُتَتَابِعًا غَزِيرًا.\nأَطوَارًاعَلَى مَرَاحِلَ مُختَلِفَةٍ: نُطفَةً، ثُمَّ عَلَقَةً، وَهَكَذَا.\nفِجَاجًاوَاسِعَةً.\nلاَ تَذَرُنَّلاَ تَترُكُنَّ.\nدَيَّارًاأَحَدًا حَيًّا عَلَى الأَرضِ يَدُورُ وَيَتَحَرَّكُ.\nتَبَارًاهَلاَكًا وَخُسرَانًا.\ndeeds\nتأمل في خلق السموات والأرض واستخرج فائدتين.\nقل: \"اللهم إنا ندرأ بك في نحور الأعداء، ونعوذ بك من شرورهم\".\nقل: \"رب اغفر لي، ولوالدي، ولمن دخل بيتي مؤمنًا، وللمؤمنين والمؤمنات، ولا تزد الظالمين إلا تبارًا\".\nguid\nكثرة الاستغفار جالبة للمطر، ودافعة للفقر، وعلاج للعقم.\nفي كل مجتمع دعاة خير ودعاة شر.\nوجوب توقير الله وتعظيمه بتوحيده وعدم الإشراك به.\nrefl\nفَقُلۡتُ ٱسۡتَغۡفِرُواْ رَبَّكُمۡ إِنَّهُۥ كَانَ غَفَّارٗا ١٠ يُرۡسِلِ ٱلسَّمَآءَ عَلَيۡكُم مِّدۡرَارٗا ١١\nفي الآية دليل على أن الاستغفار يوجب نزول الأمطار؛ ولذلك خرج عمر بن الخطاب إلى الاستسقاء فلم يزد على أن استغفر ثم انصرف، فقيل له: ما رأيناك استسقيت؟! فقال: \"والله لقد استسقيت أبلغ الاستسقاء\". ابن جزي: ٢/٤٩٥.\nبيّن مكانة الاستغفار في الاستسقاء.\nمَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا ١٣\nأي: ما لكم لا تخافون لله عظمة وقدرة على أحدكم بالعقوبة، أي: أيُّ عذر لكم في ترك الخوف من الله؟! القرطبي: ٢١/٢٥٥.\nما المراد بقوله ﴿لَا تَرۡجُونَ﴾ في الآية؟\nمَّا لَكُمۡ لَا تَرۡجُونَ لِلَّهِ وَقَارٗا ١٣\nلو عظَّموا الله وعرفوا حق عظمته وحَّدوه وأطاعوه وشكروه؛ فطاعته سبحانه واجتناب معاصيه والحياء منه بحسب وقاره في القلب. ابن القيم: ٣/٢٠٣.\nما علامة توقير القلب لله سبحانه؟\nقَالَ نُوحٞ رَّبِّ إِنَّهُمۡ عَصَوۡنِي وَٱتَّبَعُواْ مَن لَّمۡ يَزِدۡهُ مَالُهُۥ وَوَلَدُهُۥٓ إِلَّا خَسَارٗا ٢١\nفإن البسط لهم في الدنيا كان سببًا لطغيانهم وبطرهم، واتباعهم لأهوائهم حتى كفروا واستغلوا غيرهم، فغلبوا عليهم، فكانوا سببًا في شقائهم وخسارتهم بخسارتهم. البقاعي: ٢٠/٤٤٧.\nوضح شؤم اتباع أهل الأموال والأهواء وترك اتباع أهل الصلاح.\nإِنَّكَ إِن تَذَرۡهُمۡ يُضِلُّواْ عِبَادَكَ وَلَا يَلِدُوٓاْ إِلَّا فَاجِرٗا كَفَّارٗا ٢٧\nأي: بقاؤهم مفسدة محضة لهم ولغيرهم؛ وإنَّما قال نوح -عليه السلام- ذلك لأنه مع كثرة مخالطته إياهم ومزاولته لأخلاقهم علم بذلك نتيجة أعمالهم؛ لا جَرَم أن الله استجاب دعوته فأغرقهم أجمعين، ونجّى نوحًا ومن معه من المؤمنين. السعدي: ٨٨٩.\nلماذا دعا نوح على قومه؟\nرَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ\nيؤخذ من هذا أن سنة الدعاء أن يقدم الإنسان الدعاء لنفسه على الدعاء لغيره. ابن جزي: ٢/٤٩٥.\nما الذي يستفاد من دعاء نوح -عليه السلام-؟\nرَّبِّ ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِمَن دَخَلَ بَيۡتِيَ مُؤۡمِنٗا وَلِلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِۖ\nخص المذكورين لتأكد حقهم، وتقديم برهم، ثم عمم الدعاء. السعدي: ٨٩٠.\nلماذا خص الوالدين قبل المؤمنين بالدعاء؟"],[572,"§الجن\nwords\nجَدُّ رَبِّنَاعَظَمَةُ رَبِّنَا، وَجَلاَلُهُ، وَغِنَاهُ.\nسَفِيهُنَاإِبلِيسُ.\nرَهَقًاطُغيانًا، وَسَفَهًا.\nمَقَاعِدَ لِلسَّمعِمَوَاضِعَ؛ لِنَستَمِعَ إِلَى أَخبَارِهَا.\nرَصَدًاأُرصِدَ لَهُ؛ لِيُرمَى بِهِ.\nطَرَائِقَ قِدَدًافِرَقًا وَمَذَاهِبَ مُختَلِفَةً.\ndeeds\nاقرأ آيات من كتاب الله مستحضرًا استماع الملائكة والجن لقراءتك؛ لعله يكتب لك أجر استماعهم.\nادع قبل النوم بهذا الدعاء: \"اللهم أسلمت نفسي إليك، وفوضت أمري إليك، ووجهت وجهي إليك، وألجأت ظهري إليك؛ رغبةً ورهبةً إليك، لا ملجأ ولا مَنجى منك إلا إليك، آمنت بكتابك الذي أنزلت، وبنبيك الذي أرسلت\".\nاستعذ بكلمات الله التامات من شر ما خلق في الصباح والمساء.\nguid\nمن عقيدة المؤمن الإيمان بالجن.\nتعظيم الله تبارك وتعالى.\nالشـرك لا يـزيد العبد إلا ضـعفًا، والتـوحيد يزيـد العبـد قـوةً وعزًّا.\nrefl\nيَهۡدِيٓ إِلَى ٱلرُّشۡدِ فَـَٔامَنَّا بِهِۦۖ وَلَن نُّشۡرِكَ بِرَبِّنَآ أَحَدٗا ٢\nفي هذا توبيخ للكفار من بني آدم؛ حيث آمنت الجن بسماع القرآن مرة واحدة، وانتفعوا بسماع آيات يسيرة منه، وأدركوا بعقولهم أنه كلام الله وآمنوا به، ولم ينتفع كفار الإنس. الشوكاني: ٥/٣٠٣-٣٠٤.\nماذا أفاد إيمان الجن فور سماعهم القرآن الكريم؟\nوَأَنَّا ظَنَنَّآ أَن لَّن تَقُولَ ٱلۡإِنسُ وَٱلۡجِنُّ عَلَى ٱللَّهِ كَذِبٗا ٥\nهذا مرشد إلى أنه لا ينبغي التقليد في شيء؛ لأن الثقة بكل أحد عجز، وإنَّما ينكشف ذلك بالتجربة، والتقليد قد يجر إلى الكفر المهلك هلاكًا أبديًا. وإليه أرشد النبي -صلى الله عليه وسلم- فيما أخرجه الشيخان عن النعمان بن بشير -رضي الله عنه- بأن: «من اتقى الشبهات استبرأ لدينه وعرضه»؛ وفي ذلك غاية الحث على أن الإنسان لا يُقدِم ولا يُحجم في أصول الدين إلا بقاطع. البقاعي: ٢٠/٤٧١.\nمتى يستحسن التقليد؟ ومتى يذم؟\nوَأَنَّهُۥ كَانَ رِجَالٞ مِّنَ ٱلۡإِنسِ يَعُوذُونَ بِرِجَالٖ مِّنَ ٱلۡجِنِّ فَزَادُوهُمۡ رَهَقٗا ٦\nوالمعنى: أن الجن زادوا الإنس ضلالًا وإثمًا لما عاذوا بهم، أو زادوهم تخويفًا لما رأوا ضعف عقولهم. وقيل: ضمير الفاعل للإنس، وضمير المفعول للجن: والمعنى إن الإنس زادوا الجن تكبرًا وطغيانًا لمَّا عاذوا بهم؛ حتى كان الجن يقول: أنا سيد الجن والإنس. ابن جزي: ٢/٤٩٥.\nبيّن ضرر لجوء بعض الناس إلى السحرة والمشعوذين والشياطين.\nوَأَنَّا لَا نَدۡرِيٓ أَشَرٌّ أُرِيدَ بِمَن فِي ٱلۡأَرۡضِ أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدٗا ١٠\nوأسند فعل إرادة الشر إلى المجهول، ولم يسند إلى الله تعالى مع أن مقابله أسند إليه بقوله: ﴿أَمۡ أَرَادَ بِهِمۡ رَبُّهُمۡ رَشَدًا﴾ جريًا على واجب الأدب مع الله تعالى في تحاشي إسناد الشر إليه. ابن عاشور: ٢٩/٢٣١.\nلماذا لم يُسنِدوا إرادة الشر إلى الله تعالى بينما أسندوا إرادة الخير إليه، مع أن الله هو المقدر الفاعل؟\nوَأَنَّا مِنَّا ٱلصَّٰلِحُونَ وَمِنَّا دُونَ ذَٰلِكَۖ كُنَّا طَرَآئِقَ قِدَدٗا ١١\nفلما قاموا مقام دعوة إخوانهم إلى اتباع طريق الخير لم يصارحوهم بنسبتهم إلى الإِفساد، بل ألهموا وقالوا: ﴿مِنَّا ٱلصَّٰلِحُونَ﴾، ثم تلطفوا فقالوا: ﴿وَمِنَّا دُونَ ذَٰلِكَۖ﴾. ابن عاشور: ٢٩/٢٣٢.\nما الأدب الذي يخرج به الداعية من هذه الآية؟\nوَأَنَّا لَمَّا سَمِعۡنَا ٱلۡهُدَىٰٓ ءَامَنَّا بِهِۦۖ فَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا ١٣\nفلا يخاف بخسًا ولا رهقًا؛ لأنه لم يبخس أحدًا حقًا، ولا رهقه ظلمًا؛ فلا يخاف جزاءهما. الألوسي: ١٥/١٠٠\nالجزاء من جنس العمل؛ وضّح ذلك من الآية.\nفَمَن يُؤۡمِنۢ بِرَبِّهِۦ فَلَا يَخَافُ بَخۡسٗا وَلَا رَهَقٗا ١٣\nقال ابن عباس -رضي الله عنهما-: \"لا يخاف أن ينقص من حسناته ولا أن يزاد في سيئاته؛ لأن البخس النقصان، والرهق العدوان\". القرطبي: ٢١/٢٩٢.\nهل يحتمل أن ينقَص من حسنات العبد أو يزاد في سيئاته على وجه الظلم له؟"],[573,"§الجن\nwords\nوَأَلَّوِ استَقَامُواوَأَنَّهُ لَوِ استَقَامَ الكُفَّارُ.\nالطَّرِيقَةِدِينِ الإِسلاَمِ.\nغَدَقًاكَثِيرًا.\nصَعَدًاشَدِيدًا شَاقًّا.\nلِبَدًاجَمَاعَاتٍ مُتَرَاكِبَةً بَعضُهَا فَوقَ بَعضٍ، مِن شِدَّةِ ازدِحَامِهِم لِسَمَاعِ القُرآنِ مِنهُ.\nيُجِيرَنِييُنقِذَنِي.\ndeeds\nقل: \"لا إله إلا الله وحده لا شريك له، له الملك وله الحمد، وهو على كل شيء قدير\" عشر مرات.\nادع الله في المسجد وبين الأذان والإقامة أن يحقق حاجة من حاجاتك.\nادع الله بهذا الدعاء: \"اللهم إني أعوذ برضاك من سخطك، وبعفوك من عقوبتك\".\nguid\nالنفع والضر بيد الله فلا يتعلق قلبك بغير الله.\nاختصاص الله تعالى بعلم الغيب.\nعظمة الله وأنه محيط بكل شيء -سبحانه وتعالى-.\nrefl\nوَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا ١٦\nوالطريقة هي طريقة الإسلام وطاعة الله؛ فالمعنى: لو استقاموا على ذلك لوسع الله أرزاقهم؛ فهو كقوله: ﴿وَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾ [الأعراف: ٩٦]. ابن جزي: ٢/٤٩٧.\nبيّن ثمرة استقامة الناس في الدنيا من خلال هذه الآية؟\nوَأَلَّوِ ٱسۡتَقَٰمُواْ عَلَى ٱلطَّرِيقَةِ لَأَسۡقَيۡنَٰهُم مَّآءً غَدَقٗا ١٦\nقال عمر -رضي الله عنه-: \"أينما كان الماء كان المال، وأينما كان المال كانت الفتنة\"؛ وضُرب الماء الغدق الكثير لذلك مثلًا؛ لأن الخير والرزق كله بالمطر يكون، فأقيم مقامه. القرطبي: ٢١/٢٩٥.\nلماذا ذكر الماء في الآية؟\nوَأَنَّ ٱلۡمَسَٰجِدَ لِلَّهِ فَلَا تَدۡعُواْ مَعَ ٱللَّهِ أَحَدٗا ١٨\nقيل: المعنى أفردوا المساجد لذكر الله، ولا تتخذوها هزوا ومتجرًا ومجلسًا ولا طرقًا، ولا تجعلوا لغير الله فيها نصيبًا. القرطبي:٢١/٣٠٠.\nبماذا خص الله -سبحانه وتعالى- المساجد؟\nقُلۡ إِنِّي لَآ أَمۡلِكُ لَكُمۡ ضَرّٗا وَلَا رَشَدٗا ٢١\nفيه تهديد عظيم وتوكيل إلى الله -جل وعلا- وأنه سبحانه هو الذي يجزيه بحسن صنيعه وسوء صنيعهم. الألوسي:١٥/١٠٥.\nما دلالة نفي النفع والضر عن النبي -صلى الله عليه وسلم-؟\nقُلۡ إِنِّي لَن يُجِيرَنِي مِنَ ٱللَّهِ أَحَدٞ وَلَنۡ أَجِدَ مِن دُونِهِۦ مُلۡتَحَدًا ٢٢\nأي: لا أحد أستجير به ينقذني من عذاب الله، وإذا كان الرسول الذي هو أكمل الخلق لا يملك ضرًا ولا رشدًا، ولا يمنع نفسه من الله شيئًا إن أراده بسوء؛ فغيره من الخلق من باب أولى وأحرى. السعدي: ٨٩١.\nدلت الآية على ضلال من تعلقت قلوبهم بالأولياء والصالحين؛ بيّن ذلك.\nعَٰلِمُ ٱلۡغَيۡبِ فَلَا يُظۡهِرُ عَلَىٰ غَيۡبِهِۦٓ أَحَدًا ٢٦ إِلَّا مَنِ ٱرۡتَضَىٰ مِن رَّسُولٖ\nهذا يعم الرسول الملكي والبشري. ابن كثير: ٤/٤٣٣.\nهل الاطلاع على بعض الغيب يختص بالرسل البشريين؟ وهل الملائكة يعلمون الغيب؟\nلِّيَعۡلَمَ أَن قَدۡ أَبۡلَغُواْ رِسَٰلَٰتِ رَبِّهِمۡ وَأَحَاطَ بِمَا لَدَيۡهِمۡ وَأَحۡصَىٰ كُلَّ شَيۡءٍ عَدَدَۢا ٢٨\nوالمعنى: أن علمه سبحانه بالأشياء ليس على وجه الإجمال، بل على وجه التفصيل؛ أي: أحصى كل فرد من مخلوقاته على حدة. الشوكاني: ٥/٣١٣.\nهل علم الله بالأشياء على وجه الإجمال أم على وجه التفصيل؟"],[574,"§المزمل\nwords\nالمُزَّمِّلُأَصلُهَا: المُتَزَمِّلُ، أَيِ: المُتَلَفِّفُ بِثِيَابِهِ.\nوَرَتِّلِاقرَأ بِتُؤَدَةٍ وَتَمَهُّلٍ؛ مُبَيِّنًا الحُرُوفَ وَالوُقُوفَ.\nوَتَبَتَّلانقَطِع لِعِبَادَتِهِ.\nأُولِي النَّعمَةِأَصحَابَ النَّعِيمِ وَالتَّرَفِ.\nأَنكَالًاقُيُودًا ثَقِيلَةً.\nذَا غُصَّةٍيَنشَبُ فِي الحُلُوقِ، لاَ يُستَسَاغُ؛ لِكَرَاهَتِهِ.\nتَرجُفُتَضطَرِبُ.\nكَثِيبًارَملًا مُجتَمِعًا.\nمَهِيلًاسَائِلًا مُتَنَاثِرًا.\nوَبِيلًاشَدِيدًا.\ndeeds\nاحرص على قيام هذه الليلة بإحدى عشرة ركعة.\nرَتِّل عشر آيات لهذا اليوم وذلك بإتقان التجويد وتعلم مواطن الوقوف فيها.\nقل: \"حسبي الله ونعم الوكيل\".\nguid\nالحرص على الصلة بالله في كل وقت.\nالصبر على الأذى.\nهول يوم القيامة.\nrefl\nيَٰٓأَيُّهَا ٱلۡمُزَّمِّلُ ١\nوفي خطابه بهذا الاسم فائدتان؛ إحداهما: الملاطفة؛ فإن العرب إذا قصدت ملاطفة المخاطب وترك المعاتبة سموه باسم مشتق من حالته التي هو عليها... والفائدة الثانية: التنبيه لكل متزمل راقد ليله ليتنبه إلى قيام الليل وذكر الله تعالى فيه. القرطبي: ٢١/٣١٦.\nما سر الخطاب بقوله: (المزمل)؟\nنِّصۡفَهُۥٓ أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا ٣ أَوۡ زِدۡ عَلَيۡهِ\nإن قيل: لم قيد النقص من النصف بالقلة فقال: ﴿أَوِ ٱنقُصۡ مِنۡهُ قَلِيلًا﴾، وأطلق في الزيادة؛ فقال: ﴿أَوۡ زِدۡ عَلَيۡهِ﴾، ولم يقل: \"قليلًا\"؟ فالجواب: أن الزيادة تحسن فيها الكثرة؛ فلذلك لم يقيدها بالقلة بخلاف النقص، فإنه لو أطلقه لاحتمل أن ينقص من النصف كثيرًا. ابن جزي: ٢/٥٠١.\nلماذا قيد النقصان بالقلة ولم يقيده بذلك في الزيادة؟\nوَرَتِّلِ ٱلۡقُرۡءَانَ تَرۡتِيلًا ٤\nالترتيل هو التمهل والمد وإشباع الحركات وبيان الحروف؛ وذلك مُعينٌ على التفكر في معاني القرآن، بخلاف [الهذ] الذي لا يفقه صاحبه ما يقول. وكان رسول الله -صلى الله عليه وسلم- يُقَطِّع قراءته حرفًا حرفًا، ولا يمرُّ بآية رحمة إلا وقف وسأل، ولا يمرّ بآية عذاب إلا وقف وتعوَّذ. ابن جزي: ٢/٥٠١.\nما فائدة الترتيل؟\nإِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا ٦\nأي: أجمع للخاطر في أداء القراءة وتفهمها من قيام النهار؛ لأنه وقت انتشار الناس، ولغط الأصوات، وأوقات المعاش. ابن كثير: ٤/٤٣٦.\nما الذي يميز قراءة الليل عن قراءة النهار؟\nوَٱذۡكُرِ ٱسۡمَ رَبِّكَ وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلٗا ٨\nجاء على التفعيل لسِرٍّ لطيف: فإن في هذا الفعل إيذانًا بالتدريج، والتكلف، والتعمل، والتكثر، والمبالغة. ابن القيم:٣/٢١٢.\nماذا نستفيد من التعبير في قوله تعالى: ﴿وَتَبَتَّلۡ إِلَيۡهِ تَبۡتِيلًا﴾؟\nوَذَرۡنِي وَٱلۡمُكَذِّبِينَ أُوْلِي ٱلنَّعۡمَةِ وَمَهِّلۡهُمۡ قَلِيلًا ١١\nووصفهم بــ﴿أُوْلِي ٱلنَّعۡمَةِ﴾ توبيخًا لهم بأنهم كذَّبوا لغرورهم وبطرهم بسعة حالهم، وتهديدًا لهم بأن الذي قال: (ذرني والمكذبين) سيزيل عنهم ذلك التنعم. ابن عاشور: ٢٩/٢٦٩.\nما فائدة وصف الله تعالى المكذبين بأنهم ﴿أُوْلِي ٱلنَّعۡمَةِ﴾؟\nإِنَّآ أَرۡسَلۡنَآ إِلَيۡكُمۡ رَسُولٗا شَٰهِدًا عَلَيۡكُمۡ كَمَآ أَرۡسَلۡنَآ إِلَىٰ فِرۡعَوۡنَ رَسُولٗا ١٥\nواختير لهم [أي كفار مكة] ضرب المثل بفرعون مع موسى -عليه السلام-؛ لأن الجامع بين حال أهل مكة وحال أهل مصر في سبب الإعراض عن دعوة الرسول هو مجموع ما هم عليه من عبادة غير الله، وما يملأ نفوسهم من التكبر والتعاظم على الرسول المبعوث إليهم. ابن عاشور: ٢٩/٢٧٣.\nلماذا اختير ضرب المثل بفرعون مع موسى؟"],[575,"§المزمل ، المدثر\nwords\nلَن تُحصُوهُلَن يُمكِنَكُم قِيَامُ اللَّيلِ كُلِّهِ.\nالمُدَّثِّرُأَصلُهُ: المُتَدَثِّرُ، وَهُوَ المُتَغَطِّي بِثِيَابِهِ.\nوَالرُّجزَالأَصنَامَ، وَأَعمَالَ الشِّركِ.\nوَلاَ تَمنُن تَستَكثِرُلاَ تُعطِ العَطِيَّةَ، كَي تَلتَمِسَ أَكثَرَ مِنهَا.\nنُقِرَ فِي النَّاقُورِنُفِخَ فِي الصُّورِ نَفخَةُ البَعثِ.\nسَأُرهِقُهُ صَعُودًاسَأُكَلِّفُهُ عَذَابًا شَاقًّا لاَ رَاحَةَ لَهُ فِيهِ.\nوقَدَّرَهَيَّأَ مَا يَقُولُهُ فِي الطَّعنِ فِي القُرآنِ، وَمَن جَاءَ بِهِ.\ndeeds\nاحرص الليلة على قيام الليل ولو بثلاث ركعات.\nصل الصلوات الخمس مع الجماعة.\nأخبر مسلمًا أن من التطهير الذي يحبه الله تطهير الثياب.\nguid\nتيسير الله على عباده ورحمته بالأمة.\nالدعوة إلى الله تنافي الكسل.\nتذكر اليوم الآخر وأنه عسير.\nrefl\n۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ أَدۡنَىٰ مِن ثُلُثَيِ ٱلَّيۡلِ وَنِصۡفَهُۥ وَثُلُثَهُۥ وَطَآئِفَةٞ مِّنَ ٱلَّذِينَ مَعَكَۚ\nوافتتاح الكلام ب﴿۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ﴾ يشعر بالثناء عليه لوفائه بحق القيام الذي أُمِر به، وأنه كان يبسط إليه ويهتم به، ثم يقتصر على القدر المعين فيه النصف أو أنقص منه قليلًا أو زائد عليه، بل أخذ بالأقصى -وذلك ما يقرب من ثلثي الليل- كما هو شأن أولي العزم. ابن عاشور: ٢٩/٢٨٠.\nما مناسبة افتتاح الآية الكريمة بقوله تعالى: ﴿۞إِنَّ رَبَّكَ يَعۡلَمُ أَنَّكَ تَقُومُ﴾؟\nعَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ\nذكر سبحانه عذرهم فقال: ﴿عَلِمَ أَن سَيَكُونُ مِنكُم مَّرۡضَىٰ﴾ فلا يطيقون قيام الليل، ﴿وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ﴾ أي: يسافرون فيها للتجارة والأرباح؛ يطلبون من رزق الله ما يحتاجون إليه في معاشهم، فلا يطيقون قيام الليل، ﴿وَءَاخَرُونَ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ﴾ يعني: المجاهدين؛ فلا يطيقون قيام الليل. ذكر سبحانه ها هنا ثلاثة أسباب مقتضية للترخيص ورفع وجوب قيام الليل، فرفعه عن جميع الأمة لأجل هذه الأعذار التي تنوب بعضهم. الشوكاني: ٥/٣٢٢.\nما أعذار ترك قيام الليل المذكورة في الآية الكريمة؟\nوَٱسۡتَغۡفِرُواْ ٱللَّهَۖ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمُۢ ٢٠\nوجملة ﴿إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ﴾ تعليل للأمر بالاستغفار؛ أي: لأن الله كثير المغفرة شديد الرحمة. والمقصود من هذا التعليل الترغيب والتحريض على الاستغفار بأنه مرجو الإجابة. وفي الإتيان بالوصفين الدالين على المبالغة في الصفة إيماء إلى الوعد بالإجابة. ابن عاشور: ٢٩/٢٩٠.\nما فائدة ختام الآية الكريمة بقوله تعالى: ﴿إِنَّ ٱللَّهَ غَفُورٌ رَّحِيمٌ﴾؟\nوَثِيَابَكَ فَطَهِّرۡ ٤\nويحتمل أن المراد بثيابه الثياب المعروفة، وأنه مأمور بتطهيرها عن جميع النجاسات في جميع الأوقات، خصوصًا عند الدخول في الصلوات. وإذا كان مأمورًا بتطهير الظاهر فإن طهارة الظاهر من تمام طهارة الباطن. السعدي: ٨٩٥.\nكيف يدل الأمر بتطهير الثياب على تطهير القلوب من أمراضها؟\nوَثِيَابَكَ فَطَهِّرۡ ٤\nعن محمد بن سيرين: ﴿وَثِيَابَكَ فَطَهِّرۡ﴾ قال: \"اغسلها بالماء\". حدثني يونس، قال: أخبرنا ابن وهب، قال: قال ابن زيد في قوله: ﴿وَثِيَابَكَ فَطَهِّرۡ﴾ قال: \"كان المشركون لا يتطهرون، فأمره أن يتطهر ويطهر ثيابه\". الطبري: ٢٣/١٢.\nما المقصود بتطهير الثياب في الآية؟\nفَذَٰلِكَ يَوۡمَئِذٖ يَوۡمٌ عَسِيرٌ ٩ عَلَى ٱلۡكَٰفِرِينَ غَيۡرُ يَسِيرٖ ١٠\nقال الزمخشري إن ﴿غَيۡرُ يَسِيرٍ﴾ كان يكفي عنها ﴿يَوۡمٌ عَسِيرٌ﴾؛ إلا أنه ليبين لهم أن عسره لا يرجى تيسيره كعسر الدنيا، وأن فيه زيادة وعيد للكافرين، ونوع بشارة للمؤمنين لسهولته عليهم. ولعل المعنيين مستقلان، وأن قوله تعالى: ﴿يَوۡمٌ عَسِيرٌ﴾ هذا كلام مستقل وصف لهذا اليوم، وبيان للجميع شدة هوله. الشنقيطي: ٨/٣٦٣.\nما وجه المقابلة بين (عسير) و(يسير) في الآيتين؟\nوَبَنِينَ شُهُودٗا ١٣\nلا يغيبون، أَي: حضورًا عنده لا يسافرون بالتجارات، بل مواليهِم وأُجراؤهم يتولَّون ذلكَ عنهم، وهم قُعود عند أَبيهِم يتمتع بهِم ويتملَّى بهِم،... وهذا أَبلَغ في النعمةِ؛ وهو إِقَامتهم عنده. ابن كثير: ٤/٤٤٢.\nما النعمة في كون أبناء الرجل شهودًا عنده؟"],[576,"§المدثر\nwords\nفَقُتِلَغُلِبَ وَقُهِرَ.\nنَظَرَتَأَمَّلَ فِيمَا هَيَّأَ مِنَ الطَّعنِ.\nعَبَسَقَطَّبَ وَجهَهُ.\nوَبَسَرَاشتَدَّ فِي العُبُوسِ لَمَّا ضَاقَت عَلَيهِ الحِيَلُ فِي الطَّعنِ.\nأَدبَرَرَجَعَ مُعرِضًا عَنِ الحَقِّ.\nيُؤثَرُيُنقَلُ عَنِ الأَوَّلِينَ.\nسَأُصلِيهِ سَقَرَسَأُدخِلُهُ جَهَنَّمَ؛ كَي يَصلَى حَرَّهَا.\nلَوَّاحَةٌ لِلبَشَرِمُحرِقَةٌ لِلجُلُودِ، مُغَيِّرَةٌ لِلبَشَرَةِ.\nمَا سَلَكَكُممَا أَدخَلَكُم.\ndeeds\nأَدِّ الصلوات الخمس مع المصلين في المسجد.\nأطعم مسكينًا حتى تنجو من النار.\nقل: \"اللهم إني أعوذ بك أن أقول زورًا، أو أغشى فجورًا\"، وتجنب الحديث في الكلام الباطل وما لا علم لك فيه.\nguid\nعِظَم خَلق الملائكة.\nيقسم الله تعالى بما شاء من خلقه، وليس للإنسان أن يقسم إلا بالله تعالى.\nالجنة جزاء أصحاب اليمين.\nrefl\nوَمَا جَعَلۡنَآ أَصۡحَٰبَ ٱلنَّارِ إِلَّا مَلَٰٓئِكَةٗۖ وَمَا جَعَلۡنَا عِدَّتَهُمۡ إِلَّا فِتۡنَةٗ لِّلَّذِينَ كَفَرُواْ لِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا وَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ وَلِيَقُولَ ٱلَّذِينَ فِي قُلُوبِهِم مَّرَضٞ وَٱلۡكَٰفِرُونَ مَاذَآ أَرَادَ ٱللَّهُ بِهَٰذَا مَثَلٗاۚ كَذَٰلِكَ يُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهۡدِي مَن يَشَآءُۚ وَمَا يَعۡلَمُ جُنُودَ رَبِّكَ إِلَّا هُوَۚ وَمَا هِيَ إِلَّا ذِكۡرَىٰ لِلۡبَشَرِ ٣١\nوهذا حال القلوب عند ورود الحق المنَزل عليها: قلب يفتتن به كفرًا وجحودًا، وقلب يزداد به إيمانًا وتصديقًا، وقلب يَتَيَقَّنه فتقوم عليه به الحجة، وقلب يوجب له حيرةً وعمىً فلا يدري ما يراد به. ابن القيم: ٣/٢١٦.\nما أنواع القلوب عند سماع الحق؟\nلِيَسۡتَيۡقِنَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَيَزۡدَادَ ٱلَّذِينَ ءَامَنُوٓاْ إِيمَٰنٗا\nبيان أن الواجب على المؤمن المبادرة بالتصديق والانقياد، ولو لم يعلم الحكمة أو السر أو الغرض؛ بناء على أن الخبر من الله تعالى وهو أعلم. الشنقيطي: ٨/٣٦٥.\nهل لا بد أن يعرف المسلم الحكمة أو السر في كل أمر في الإسلام لكي يؤمن به ويصدقه؟\nوَلَا يَرۡتَابَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ وَٱلۡمُؤۡمِنُونَ\nأي: ليزول عنهم الريب والشك. وهذه مقاصد جليلة يعتني بها أولو الألباب؛ وهي: السعي في اليقين، وزيادة الإيمان في كل وقت وكل مسألة من مسائل الدين، ودفع الشكوك والأوهام التي تعرض في مقابلة الحق. السعدي: ٨٩٧.\nدلت الآية على وجوب التيقن في كل مسائل الدين؛ وضّح ذلك.\nكُلُّ نَفۡسِۢ بِمَا كَسَبَتۡ رَهِينَةٌ ٣٨ إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ ٣٩\n﴿إِلَّآ أَصۡحَٰبَ ٱلۡيَمِينِ﴾ أي: الذين تقدم وصفهم؛ وهم الذين تحيَّزوا إلى الله؛ فائتمروا بأوامره، وانتهوا بنواهيه؛ فإنهم لا يرتهنون بأعمالهم، بل يرحمهم الله فيقبل حسناتهم، ويتجاوز عن سيئاتهم. البقاعي: ٢١/٧١.\nمن أصحاب اليمين؟\nمَا سَلَكَكُمۡ فِي سَقَرَ ٤٢ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ ٤٣\nتنبيهًا على أن رسوخ القدم في الصلاة مانع من مثل حالهم، وعلى أن الصلاة أعظم الأعمال، وأن الحساب بها يقدم على غيرها. البقاعي: ٢١/٧٥.\nما سبب دخول هؤلاء في سقر؟ وماذا تستفيد من ذلك؟\nمَا سَلَكَكُمۡ فِي سَقَرَ ٤٢ قَالُواْ لَمۡ نَكُ مِنَ ٱلۡمُصَلِّينَ ٤٣\nفي الآية إشارة إلى أن المسلم الذي أضاع إقامة الصلاة وإيتاء الزكاة مستحق حظًا من سقر على مقدار إضاعته، وعلى ما أراد الله من معادلة حسناته وسيئاته، وظواهره وسرائره. ابن عاشور: ٢٩/٣٢٨.\nفي هذه الآية إشارة إلى خطورة التهاون في الصلاة والزكاة للمسلم؛ بين ذلك.\nوَكُنَّا نَخُوضُ مَعَ ٱلۡخَآئِضِينَ ٤٥\nأي نشرع في الباطل مع الشارعين... وأريد بالباطل ما لا ينبغي من القول والفعل. وَعُدَّ من ذلك حكاية ما يجري بين الزوجين في الخلوة مثلًا، وحكايةً أحوال الفسقة بأقسامهم على وجه الالتذاذ والاستئناس بها. الألوسي: ١٥/١٤٧.\nإطلاق العنان للسان مهلكة؛ وضّح ذلك من الآية."],[577,"§المدثر ، القيامة\nwords\nحُمُرٌحُمُرٌ وَحشِيَّةٌ شَدِيدَةُ النِّفَارِ.\nقَسوَرَةٍأَسَدٍ كَاسِرٍ.\nاللَّوَّامَةِالنَّفسِ الَّتِي تَلُومُ صَاحِبَهَا.\nنُسَوِّيَ بَنَانَهُنَجعَلَ أَصَابِعَ يَدَيهِ وَرِجلَيهِ شَيئًا مُستَوِيًا؛ كَخُفِّ البَعِيرِ، أَو نُعِيدَ خَلقَهَا كَمَا كَانَت.\nأَيَّانَمَتَى؟!\nبَرِقَ البَصَرُتَحَيَّرَ البَصَرُ وَدُهِشَ لأِهوَالِ القِيَامَةِ.\nلاَ وَزَرَلاَ مَلجَأَ وَلاَ مَنجَى لَهُ مِنَ اللهِ.\nالمُستَقَرُّالمَرجِعُ وَالمَصِيرُ.\nوَلَو أَلقَى مَعَاذِيرَهُلَو جَاءَ بِكُلِّ مَعذِرَةٍ يَعتَذِرُ بِهَا مَا قُبِلَت.\ndeeds\nسَلِ الله أن تنال شفاعة نبيك محمد -صلى الله عليه وسلم-، واستعن على ذلك بصالح الأعمال.\nعاتب نفسك قبل أن تندم على أعمالك.\nقل: \"اللهم اغفر لي ما قدمت وما أخرت\".\nguid\nأقبِل على الدروس والمواعظ ولا تكن من المعرضين عن التذكرة.\nالله سبحانه هو الذي يُتقى عذابه، ويُستغفَر من الذنوب.\nأهمية محاسبة النفس.\nrefl\nفَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ ٤٨\nإيماء إلى ثبوت الشفاعة لغيرهم يوم القيامة على الجملة، وتفصيلها في صحاح الأخبار. ابن عاشور: ٢٩/٣٢٨.\nما إيماء الآية الكريمة ﴿فَمَا تَنفَعُهُمۡ شَفَٰعَةُ ٱلشَّٰفِعِينَ﴾؟\nهُوَ أَهۡلُ ٱلتَّقۡوَىٰ وَأَهۡلُ ٱلۡمَغۡفِرَةِ ٥٦\nهو أهل أن يخاف منه، وهو أهل أن يغفر ذنب من تاب إليه وأناب. ابن كثير: ٤/٤٤٧.\nإذا علمت أن الله أهل لأن يغفر الذنوب؛ فما موقفك العملي من هذا؟\nوَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ ٢\nهي التي تلوم نفسها على فعل الذنوب، أو التقصير في الطاعات؛ فإن النفوس على ثلاثة أنواع: فخيرها النفس المطمئنة، وشرها النفس الأمارة بالسوء، وبينهما النفس اللوامة. ابن جزي:٢/٥١٣.\nالنفوس أنواع؛ فما الفرق بين النفس الأمّارة والنفس اللوامة؟\nوَلَآ أُقۡسِمُ بِٱلنَّفۡسِ ٱللَّوَّامَةِ ٢\nوَنَبَّه سبحانه بكونها لوامةً على شدة حاجتها وفاقتها وضرورتها إلى من يُعَرِّفُها الخير والشر، ويدلها عليه، ويرشدها إليه، ويلهمها إياه؛ فيجعلها مريدة للخير مرشدة له، كارهة للشر مجانبة له؛ لتخلُصَ من اللوم، ومن شرِّ ما تلوم عليه. ولأنها متلوِّمة مترددة لا تثبت على حال واحدة؛ فهي محتاجة إلى من يُعَرِّفُها ما هو أنفع لها في معاشها ومعادها، فتؤثره وتلوم نفسها عليه إذا فاتها. ابن القيم: ٣/٢٢٥.\nما المقصود بالنفس اللوامة؟\nلَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ١٦\nتضمنت التأني والتثبت في تلقي العلم، وأن لا يحمل السامع شدة محبته وحرصه وطلبه عن مبادرة المعلم بالأخذ قبل فراغه من كلامه... فهكذا ينبغي لطالب العلم ولسامعه أن يصبر على معلمه حتى يقضيَ كلامه، ثم يعيده عليه، أو يسأل عما أشكل عليه منه، ولا يبادره قبل فراغه. ابن القيم: ٣/٢٣٠.\nتضمنت الآية أدبًا يجب على طلاب العلم أن يتحلوا به؛ فما هو؟\nلَا تُحَرِّكۡ بِهِۦ لِسَانَكَ لِتَعۡجَلَ بِهِۦٓ ١٦ إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ١٧ فَإِذَا قَرَأۡنَٰهُ فَٱتَّبِعۡ قُرۡءَانَهُۥ ١٨ ثُمَّ إِنَّ عَلَيۡنَا بَيَانَهُۥ ١٩\nفي هذه الآية أدب لأخذ العلم: أن لا يبادر المتعلم المعلم قبل أن يفرغ من المسألة التي شرع فيها، فإذا فرغ منها سأله عما أشكل عليه. وكذلك إذا كان في أول الكلام ما يوجب الرد أو الاستحسان أن لا يبادر برده أو قبوله، حتى يفرغ من ذلك الكلام؛ ليتبين ما فيه من حق أو باطل، وليفهمه فهمًا يتمكن به من الكلام عليه. السعدي: ٨٩٩.\nما هو أدب طالب العلم المستفاد من الآية؟\nإِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ ١٧\nقوله تعالى: ﴿إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ﴾ فيه إشارة إلى أنه نزل مفرقًا، وإشارة إلى أن جمعه على هذا النحو الموجود برعاية وعناية من الله تعالى، وتحقيقًا لقوله تعالى: ﴿إِنَّ عَلَيۡنَا جَمۡعَهُۥ وَقُرۡءَانَهُۥ﴾، ويشهد لذلك أن هذا الجمع الموجود من وسائل حفظه؛ كما تعهد تعالى بذلك، والله تعالى أعلم. الشنقيطي: ٨/٣٧٤.\nفي هذه الآية إشارة إلى أن القرآن نزل مفرّقًا، وأن جمعه على هذا النحو الموجود برعاية وعناية من الله تعالى؛ وضّح ذلك."],[578,"§القيامة ، الإنسان\nwords\nنَاضِرَةٌمُشرِقَةٌ حَسَنَةٌ.\nبَاسِرَةٌعَابِسَةٌ كَالِحَةٌ.\nفَاقِرَةٌمُصِيبَةٌ عَظِيمَةٌ تَقصِمُ فَقَارَ الظَّهرِ.\nبَلَغَتِ التَّرَاقِيَوَصَلَتِ الرُّوحُ إِلَى أَعَالِي الصَّدرِ.\nمَن رَاقٍهَل مِن رَاقٍ يَرقِيهِ وَيَشفِيهِ؟\nيَتَمَطَّىيَتَبَختَرُ فِي مِشيَتِهِ مُختَالًا.\nسُدىًهَمَلًا، لاَ يُؤمَرُ وَلاَ يُحَاسَبُ.\nعَلَقَةًقِطعَةً مِن دَمٍ جَامِدٍ.\nأَمشَاجٍمُختَلِطَةٍ مِن مَاءِ الرَّجُلِ وَمَاءِ المَرأَةِ.\ndeeds\nادع الله: \"اللهم لا تجعل الدنيا أكبر همي، ولا مبلغ علمي\".\nسَلِ الله حسن الختام.\nسَلِ الله الهداية.\nguid\nالحرص على الأعمال التي تجعل المؤمن في زمرة من ينظر إلى الله -عز وجل- يوم القيامة.\nالتفكر في خلق الإنسان.\nقراءة سورة السجدة في الركعة الأولى، وسورة الإنسان في الركعة الثانية في صلاة الفجر يوم الجمعة.\nrefl\nكَلَّا بَلۡ تُحِبُّونَ ٱلۡعَاجِلَةَ ٢٠ وَتَذَرُونَ ٱلۡأٓخِرَةَ ٢١\nلأن الدنيا نعيمها ولذاتها عاجلة، والإنسان مولع بحب العاجل، والآخرة متأخر ما فيها من النعيم المقيم؛ فلذلك غفلتم عنها وتركتموها كأنكم لم تخلقوا لها، وكأن هذه الدار هي دار القرار التي تبذل فيها نفائس الأعمار، ويسعى لها آناء الليل والنهار، وبهذا انقلبت عليكم الحقيقة، وحصل من الخسار ما حصل. السعدي: ٩٠٠.\nما سبب حب الإنسان للحياة العاجلة وتركه لنعيم الآخرة؟\nوَقِيلَ مَنۡۜ رَاقٖ ٢٧\nأي: من يرقيه -من الرقية-؛ لأنهم انقطعت آمالهم من الأسباب العادية، فلم يبق لهم إلا الأسباب الإلهية. السعدي: ٩٠٠\nما وجه بحثهم عن الراقي لعلاج المحتضر؟ ولماذا لم يبحثوا عن الأطباء المعالجين؟\nثُمَّ ذَهَبَ إِلَىٰٓ أَهۡلِهِۦ يَتَمَطَّىٰٓ ٣٣\nأي يتبختر افتخارًا بذلك... وقيل: أصله يتمطط؛ وهو: التمدد من التكسل والتثاقل؛ فهو يتثاقل عن الداعي إلى الحق. القرطبي: ٢١/٤٣٧.\nما التمطي المذموم في الآية؟\nهَلۡ أَتَىٰ عَلَى ٱلۡإِنسَٰنِ حِينٞ مِّنَ ٱلدَّهۡرِ لَمۡ يَكُن شَيۡٔٗا مَّذۡكُورًا ١\nتعريف الإنسان بحاله وابتداء أمره؛ ليعلم أن لا طريق له للكبر واعتقاد السيادة لنفسه، وأن لا يغلطه ما اكتنفه من الألطاف الربانية والاعتناء الإلهي والتكرمة؛ فيعتقد أنه يستوجب ذلك ويستحقه؛ ﴿وَمَا بِكُم مِّن نِّعۡمَةٍ فَمِنَ ٱللَّهِ﴾ [النحل: ٥٣]. البقاعي: ٢١/١٢٣.\nما الذي يدفع الإنسان الجاهل إلى الكبر؟\nإِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا ٢\n﴿مِن نُّطۡفَةٍ أَمۡشَاجٍ﴾ أي: ماء مهين مستقذر، (نبتليه) بذلك؛ لنعلم هل يرى حاله الأولى ويتفطن لها، أم ينساها وتغُرُّه نفسه. السعدي: ٩٠٠.\nبينت هذه الآية كيف يتخلص الإنسان من الغرور؛ وضّح ذلك.\nإِنَّا خَلَقۡنَا ٱلۡإِنسَٰنَ مِن نُّطۡفَةٍ أَمۡشَاجٖ نَّبۡتَلِيهِ فَجَعَلۡنَٰهُ سَمِيعَۢا بَصِيرًا ٢ إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا ٣\nأي: جعلنا له سمعًا وبصرًا يتمكن بهما من الطاعة والمعصية. ابن كثير: ٤/٤٥٣.\nلماذا ذكر الله حاستي السمع والبصر قبل قوله: ﴿إِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرًا وَإِمَّا كَفُورًا﴾؟\nإِنَّا هَدَيۡنَٰهُ ٱلسَّبِيلَ إِمَّا شَاكِرٗا وَإِمَّا كَفُورًا ٣\nوجمع بين الشاكر والكفور، ولم يجمع بين الشكور والكفور -مع اجتماعهما في معنى المبالغة- نفيًا للمبالغة في الشكر وإثباتًا لها في الكفر؛ لأن شكر الله تعالى لا يؤدى فانتفت عنه المبالغة، ولم تنتف عن الكفر المبالغة؛ فقل شكره لكثرة النعم عليه، وكثر كفره -وإن قل- مع الإحسان إليه. القرطبي: ٢١/٤٥٠.\nلماذا جاءت صيغة المبالغة في لفظة الكفر دون لفظة الشكر؟"],[579,"§الإنسان\nwords\nيَشرَبُ بِهَايَشرَبُونَ مُتَلَذِّذِينَ بِهَا.\nمُستَطِيرًافَاشِيًا مُنتَشِرًا عَلَى النَّاسِ.\nقَمطَرِيرًاشَدِيدَ العُبُوسِ.\nالأَرَائِكِالأَسِرَّةِ المُزَيَّنَةِ بِفَاخِرِ الثِّيَابِ وَالسُّتُورِ.\nزَمهَرِيرًاشِدَّةَ بَردٍ.\nوَدَانِيَةًقَرِيبَةً أَشجَارُهَا.\nوَذُلِّلَت قُطُوفُهَاسُهِّلَ لَهُم أَخذُ ثِمَارِهَا.\nقَوَارِيرَامِنَ الزُّجَاجِ.\nتُسَمَّى سَلسَبِيلًاسُمِّيَت بِذَلِكَ؛ لِسَلاَسَةِ شُربِهَا، وَسُهُولَةِ مَسَاغِهِ.\ndeeds\nأوف بنذرك إذا نذرت.\nأعط مسلمًا طعامًا تحبه من باب الإيثار على نفسك.\nقل أذكار الصباح قبل الذهاب للمدرسة أو العمل، وقل أذكار المساء قبل المغرب.\nguid\nإخلاص الأعمال لله تعالى.\nالتفكر في نعيم أهل الجنة.\nالصبر من علامات الرضى بالقضاء والقدر.\nrefl\nيُوفُونَ بِٱلنَّذۡرِ وَيَخَافُونَ يَوۡمٗا كَانَ شَرُّهُۥ مُسۡتَطِيرٗا ٧\nأي: بما ألزموا به أنفسهم لله من النذور والمعاهدات. وإذا كانوا يوفون بالنذر وهو لم يجب عليهم إلا بإيجابهم على أنفسهم، كان فعلهم وقيامهم بالفروض الأصلية من باب أولى وأحرى. السعدي: ٩٠١.\nعلى أي شيء يدل امتداح الله للأبرار بالوفاء بالنذر؟\nوَيُطۡعِمُونَ ٱلطَّعَامَ عَلَىٰ حُبِّهِۦ مِسۡكِينٗا وَيَتِيمٗا وَأَسِيرًا ٨ إِنَّمَا نُطۡعِمُكُمۡ لِوَجۡهِ ٱللَّهِ لَا نُرِيدُ مِنكُمۡ جَزَآءٗ وَلَا شُكُورًا ٩\nومن طلب من الفقراء الدعاء أو الثناء خرج من هذه الآية. ابن تيمية: ٦/٤٤١.\nمتى يكون الإطعام لوجه الله تمامًا؟\nوَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ١٢\nأي بصبرهم على الجوع وإيثار غيرهم على أنفسهم. ابن جزي:٢/٥١٩.\nما الصفة التي بسببها تَحَصَّلَ الأبرار على الجنة في هذه الآية؟\nوَجَزَىٰهُم بِمَا صَبَرُواْ جَنَّةٗ وَحَرِيرٗا ١٢ مُّتَّكِـِٔينَ فِيهَا عَلَى ٱلۡأَرَآئِكِۖ لَا يَرَوۡنَ فِيهَا شَمۡسٗا وَلَا زَمۡهَرِيرٗا ١٣\nولما كان في الصبر من حبس النفس، والخشونة التي تلحق الظاهر والباطن من: التعب والنصب والحرارة ما فيه؛ كان الجزاء عليه بالجنة التي فيها السعة، والحرير الذي فيه اللين والنعومة، والاتكاء الذي يتضمن الراحة، والظلال المنافية للحر. ابن تيمية: ٦/٤٤٥.\nلماذا كان نعيم أهل الجنة مبنيًا على السعة والنعومة؟\n۞وَيَطُوفُ عَلَيۡهِمۡ وِلۡدَٰنٞ مُّخَلَّدُونَ إِذَا رَأَيۡتَهُمۡ حَسِبۡتَهُمۡ لُؤۡلُؤٗا مَّنثُورٗا ١٩\nوأحسن من يتخذ للخدمة الولدان؛ لأنهم أخف حركة وأسرع مشيًا، ولأن المخدوم لا يتحرج إذا أمرهم أو نهاهم. ابن عاشور: ٢٩/٣٩٧.\nلماذا كان الخدم في الجنة من الولدان؟\nفَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ\nأي: كما أكرمك بما أنزل عليك فاصبر على قضائه وقدره، واعلم أنه سيدبرك بحسن تدبيره. ابن كثير: ٤/٤٥٨.\nما الفائدة من اقتران الصبر بحكم الله؟\nفَٱصۡبِرۡ لِحُكۡمِ رَبِّكَ وَلَا تُطِعۡ مِنۡهُمۡ ءَاثِمًا أَوۡ كَفُورٗا ٢٤ وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةٗ وَأَصِيلٗا ٢٥\nأي اصبر لحكمه القدري؛ فلا تسخطه، ولحكمه الديني؛ فامض عليه ولا يعوقك عنه عائق،... ولما كان الصبر يساعده القيام بعبادة الله والإكثار من ذكره أمره الله بذلك؛ فقال: ﴿وَٱذۡكُرِ ٱسۡمَ رَبِّكَ بُكۡرَةً وَأَصِيلًا﴾. السعدي: ٩٠٢.\nلماذا أمر بذكر اسم الله بكرة وأصيلًا بعد الأمر بالصبر لحكم الله؟"],[580,"§الإنسان ، المرسلات\nwords\nفَالعَاصِفَاتِ عَصفًاقَسَمٌ بِالرِّيَاحِ شَدِيدَةِ الهُبُوبِ المُهلِكَةِ.\nوَالنَّاشِرَاتِ نَشرًاقَسَمٌ بِالمَلاَئِكَةِ المُوكَلِينَ بِالسُّحُبِ يَسُوقُونَها حَيثُ شَاءَ اللهُ.\nفَالفَارِقَاتِ فَرقًاقَسَمٌ بِالمَلاَئِكَةِ الَّتِي تَنزِلُ بِما يَفرِقُ بَينَ الحَقِّ وَالبَاطِلِ.\nطُمِسَتمُحِيَت وَذَهَبَ نُورُهَا.\nفُرِجَتتَصَدَّعَت، وَتَشَقَّقَت.\nنُسِفَتتَطَايَرَت، وَتَنَاثَرَت.\nأُقِّتَتعُيِّنَ لَهُم وَقتٌ وَأَجَلٌ لِلفَصلِ بَينَهُم وَبَينَ أُمَمِهِم.\ndeeds\nأكثر هذه الليلة من التسبيح والصلاة.\nقل: \"سبحان الله وبحمده، سبحان الله العظيم\" مائة مرة.\nسَلِ الله أن يدخلك في رحمته.\nguid\nهوان الخلق على الله تعالى إذا عصوه.\nالتفكر في الرياح وأنواعها.\nشدة أهوال يوم القيامة.\nrefl\nوَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ٢٦\nوذكر الصلاة بالسجود تنبيهًا على أنه أفضل الصلاة؛ فهو إشارة إلى أن الليل موضع الخضوع. البقاعي: ٢١/١٥٧.\nلماذا عبر عن الصلاة بالسجود؟\nوَمِنَ ٱلَّيۡلِ فَٱسۡجُدۡ لَهُۥ وَسَبِّحۡهُ لَيۡلٗا طَوِيلًا ٢٦\nأي: أكثر له من السجود، ولا يكون ذلك إلا بالإكثار من الصلاة. السعدي: ٩٠٣.\nكيف تدل الآية على الندب إلى كثرة صلاة الليل؟\nنَّحۡنُ خَلَقۡنَٰهُمۡ وَشَدَدۡنَآ أَسۡرَهُمۡۖ وَإِذَا شِئۡنَا بَدَّلۡنَآ أَمۡثَٰلَهُمۡ تَبۡدِيلًا ٢٨\n﴿نَّحۡنُ خَلَقۡنَٰهُمۡ﴾ أي: أوجدناهم من العدم، ﴿وَشَدَدۡنَآ أَسۡرَهُمۡۖ﴾ أي: أحكمنا خلقتهم بالأعصاب، والعروق، والأوتار، والقوى الظاهرة والباطنة؛ حتى تم الجسم واستكمل، وتمكن من كل ما يريده. فالذي أوجدهم على هذه الحالة قادر على أن يعيدهم بعد موتهم لجزائهم. السعدي: ٩٠٣.\nما وجه الاستدلال بهذه الحياة على البعث يوم القيامة؟\nإِنَّ هَٰذِهِۦ تَذۡكِرَةٞۖ فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلٗا ٢٩ وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا ٣٠\nوقوله: ﴿فَمَن شَآءَ ٱتَّخَذَ إِلَىٰ رَبِّهِۦ سَبِيلًا﴾: علَّق اتخاذ السبيل إلى الله على مشيئة من شاء، وقيدُها: ربط مشيئة العبد بمشيئة الله تعالى في قوله: ﴿وَمَا تَشَآءُونَ إِلَّآ أَن يَشَآءَ ٱللَّهُۚ﴾، وهذه مسألة القدر. الشنقيطي: ٨/٣٩٩.\nفي هاتين الآيتين ركن من أركان الإيمان؛ فما هو؟\nوَٱلۡمُرۡسَلَٰتِ عُرۡفٗا ١ فَٱلۡعَٰصِفَٰتِ عَصۡفٗا ٢ وَٱلنَّٰشِرَٰتِ نَشۡرٗا ٣ فَٱلۡفَٰرِقَٰتِ فَرۡقٗا ٤ فَٱلۡمُلۡقِيَٰتِ ذِكۡرًا ٥\nوفي تطويل القَسَم تشويقُ السامع لتلقي المقسم عليه. ابن عاشور: ٢٩/٤١٩.\nلماذا جاء القسم في هذه السورة طويلًا؟\nوَمَآ أَدۡرَىٰكَ مَا يَوۡمُ ٱلۡفَصۡلِ ١٤\nأي: إنه أمر يستحق أن يسأل عنه ويعظم، وكل ما عُظِّم بشيء فهو أعظم منه، ولا يقدر أحد من الخلق على الوصول إلى علمه؛ لأنه لا مثل له. البقاعي: ٢١/١٧٠.\nما دلالة الاستفهام في الآية؟\nوَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ١٥\nوكرره في هذه السورة عند كل آية لمن كذب؛ لأنه قسمه بينهم على قدر تكذيبهم؛ فإن لكل مكذب بشيء عذابًا سوى تكذيبه بشيء آخر. القرطبي: ٢١/٥٠١-٥٠٢.\nلماذا كرر عذاب المكذبين في السورة؟"],[581,"§المرسلات\nwords\nمَاءٍ مَهِينٍضَعِيفٍ حَقِيرٍ؛ وَهُوَ النُّطفَةُ.\nقَرَارٍ مَكِينٍمَكَانٍ حَصِينٍ مُتَمَكِّنٍ.\nقَدَرٍوَقتٍ.\nكِفَاتًاوِعَاءً تَضُمُّ الأَحيَاءَ وَالأَموَاتَ.\nرَوَاسِيَشَامِخَاتٍ جِبَالًا ثَوَابِتَ، مُرتَفِعَاتٍ.\nفُرَاتًاعَذبًا، سَائِغًا.\nظِلٍّهُوَ دُخَانُ جَهَنَّمَ.\nذِي ثَلاَثِ شُعَبٍيَتَفَرَّعُ مِنهُ ثَلاَثُ قِطَعٍ.\nلاَ ظَلِيلٍلاَ يُظِلُّ مِن حَرِّ ذَلِكَ اليَومِ.\nكَالقَصرِكَالبِنَاءِ المُشَيَّدِ فِي العِظَمِ وَالاِرتِفَاعِ.\nجِمَالَةٌ صُفرٌكَأَنَّ الشَّرَرَ إِبِلٌ سُودٌ يَمِيلُ لَونُهَا إِلَى الصُّفرَةِ.\ndeeds\nزُرِ المقابر واتعظ بتلك الزيارة.\nاطلب من الله أن يسقيكم وينزل الغيث.\nاستعذ بالله من عذاب جهنّم ثلاثا.\nguid\nالتفكر في خلق الإنسان، ودلالة الخلق على البعث.\nالتفكر في ظل الكفار.\nفضل عاقبة المحسنين يوم القيامة.\nrefl\nأَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ كِفَاتًا ٢٥\nتضم الأحياء على ظهرها، والأموات في بطنها. وهذا يدل على وجوب مواراة الميت ودفنه، ودفن شعره وسائر ما يزيله عنه. القرطبي: ٢١/٥٠٥.\nما الحكم الشرعي المستفاد من هذه الآية؟\nإِنَّهَا تَرۡمِي بِشَرَرٖ كَٱلۡقَصۡرِ ٣٢ كَأَنَّهُۥ جِمَٰلَتٞ صُفۡرٞ ٣٣\n﴿جِمَٰلَتٌ صُفۡرٌ﴾ وهي: السود التي تضرب إلى لون فيه صفرة، وهذا يدل على أن النار مظلمة؛ لهبها وجمرها وشررها، وأنها سوداء، كريهة المرأى، شديدة الحرارة، نسأل الله العافية منها. السعدي: ٩٠٥.\nمن خلال تدبرك للآية وفهمك للمعنى، ما لون النار؟ وهل هي مظلمة أم فيها شيء من النور؟\nفَإِن كَانَ لَكُمۡ كَيۡدٞ فَكِيدُونِ ٣٩\nتعجيز لهم، وتعريض بكيدهم في الدنيا، وتقريع عليه. ابن جزي: ٢/٥٢٥.\nإذا كان الكفار يوم القيامة عاجزين ولا ينطقون؛ فكيف يحصل منهم الكيد؟\nكُلُواْ وَٱشۡرَبُواْ هَنِيٓـَٔۢا بِمَا كُنتُمۡ تَعۡمَلُونَ ٤٣\nفيه النص على أن عملهم في الدنيا سبب في تمتعهم بنعيم الجنة في الآخرة، وجاء في الحديث: (لن يدخل أحدكم الجنة بعمله)، ولا معارضة بين النصين؛ إذ الدخول بفضل من الله، وبعد الدخول يكون التوارث، وتكون الدرجات، ويكون التمتع بسبب الأعمال. فكلهم يشتركون في التفضل من الله عليهم بدخول الجنة، ولكنهم بعد الدخول يتفاوتون في الدرجات بسبب الأعمال. الشنقيطي: ٨/٤٠٤.\nما العلاقة بين الأعمال ودخول الجنة؟ وضح ذلك.\nكُلُواْ وَتَمَتَّعُواْ قَلِيلًا إِنَّكُم مُّجۡرِمُونَ ٤٦\nفيه دلالة على أن كل مجرم نهايته تمتع أيام قليلة، ثم يبقى في عذاب وهلاك أبدًا. الألوسي:١٥/١٩٧.\nعلى ماذا يدل الأمر بالتمتع والأكل للمجرمين في الدنيا؟\nوَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ٤٨\nأي أطيعوا الله تعالى واخشعوا وتواضعوا له -عز وجل- بقبول وحيه تعالى واتباع دينه سبحانه، وارفضوا هذا الاستكبار والنخوة. ﴿لَا يَرۡكَعُونَ﴾ لا يخشعون ولا يقبلون ذلك ويصرون على ما هم عليه من الاستكبار. الألوسي: ١٥/١٩٧.\nما دلالة الأمر بالركوع ورفض المشركين ذلك؟\nوَإِذَا قِيلَ لَهُمُ ٱرۡكَعُواْ لَا يَرۡكَعُونَ ٤٨ وَيۡلٞ يَوۡمَئِذٖ لِّلۡمُكَذِّبِينَ ٤٩\nومن إجرامهم أنهم إذا أُمروا بالصلاة التي هي أشرف العبادات، وقيل لهم: (اركعوا) امتنعوا من ذلك. فأيُّ إجرام فوق هذا؟! وأي تكذيب فوق هذا؟! السعدي: ٩٠٥.\nتكلم عن منزلة الصلاة من خلال تدبرك للآية."],[582,"§النبإ\nwords\nسُبَاتًارَاحَةً لأِبدَانِكُم، وَقَطعًا لأَعمَالِكُم.\nسِرَاجًا وَهَّاجًامِصبَاحًا وَقَّادًا مُضِيئًا.\nالمُعصِرَاتِالسُّحُبِ المُمطِرَةِ.\nثَجَّاجًامُنصَبًّا بِكَثرَةٍ.\nوَجَنَّاتٍ أَلفَافًابَسَاتِينَ ملتفةٌ أَشجَارُهَا.\nمِيقَاتًاوَقتًا، وَمِيعَادًا لِلفَصلِ بَينَ الخَلقِ.\nمِرصَادًاتَرصُدُ أَهلَهَا وَتَرقُبُهُم.\nأَحقَابًادُهُورًا لاَ تَنقَطِعُ.\nوَغَسَّاقًاصَدِيدَ أَهلِ النَّارِ.\nوِفَاقًاعَادِلًا، مُوَافِقًا لأَعمَالِهِم.\ndeeds\nنم الليلة مبكرًا ثم اذكر فائدتين وجدتهما من التبكير بالنوم.\nاستعذ بالله من عذاب جهنم ثلاثًا.\nتذكر ذنبًا عملته ثم استغفر الله.\nguid\nلله تعالى على خلقه نعمٌ كثيرة موجبة مزيد شكره.\nلا يزال عند أهل النار أمل أن يصلهم شيء من برد الجنة وشرابها حتى يسمعوا قوله تعالى.\nعدم الإيمان بالحساب أو الغفلة عنه سبب لتكاثر السيئات.\nrefl\nعَمَّ يَتَسَآءَلُونَ ١ عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ ٢\nذكر سبحانه تساؤلهم عن ماذا، وبيَّنه فقال: ﴿عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ﴾. فأورده سبحانه أولًا على طريقة الاستفهام مبهمًا لتتوجه إليه أذهانهم، وتلتفت إليه أفهامهم، ثم بيَّنه بما يفيد تعظيمه وتفخيمه؛ كأنه قيل: عن أي شيء يتساءلون؟ هل أخبركم به؟ ثم قيل بطريق الجواب: ﴿عَنِ ٱلنَّبَإِ ٱلۡعَظِيمِ﴾. الشوكاني: ٥/٣٦٣.\nلماذا جاء الاستفهام في بداية السورة؟\nٱلَّذِي هُمۡ فِيهِ مُخۡتَلِفُونَ ٣\nوجيء بالجملة الاسمية في صلة الموصول دون أن يقول: \"الذي يَختلفون فيه\"، أو نحو ذلك؛ لتفيد الجملة الاسمية أن الاختلاف في أمر هذا النبأ متمكن منهم ودائم فيهم؛ لدلالة الجملة الاسمية على الدوام والثبات. ابن عاشور: ٣٠/١١.\nما فائدة وقوع صلة الموصول جملة اسمية، وليس جملة فعلية؟\nأَلَمۡ نَجۡعَلِ ٱلۡأَرۡضَ مِهَٰدٗا ٦ وَٱلۡجِبَالَ أَوۡتَادٗا ٧ وَخَلَقۡنَٰكُمۡ أَزۡوَٰجٗا ٨ وَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ٩ وَجَعَلۡنَا ٱلَّيۡلَ لِبَاسٗا ١٠ وَجَعَلۡنَا ٱلنَّهَارَ مَعَاشٗا ١١ وَبَنَيۡنَا فَوۡقَكُمۡ سَبۡعٗا شِدَادٗا ١٢ وَجَعَلۡنَا سِرَاجٗا وَهَّاجٗا ١٣ وَأَنزَلۡنَا مِنَ ٱلۡمُعۡصِرَٰتِ مَآءٗ ثَجَّاجٗا ١٤\nوإنَّما ذكر الله تعالى هنا هذه المخلوقات على جهة التوقيف ليقيم الحجة على الكفار فيما أنكروه من البعث؛ كأنه يقول: إن الإله الذي قدر على خلقة هذه المخلوقات العظام قادر على إحياء الناس بعد موتهم. ابن جزي: ١/٢٥٤١.\nذكر الله المخلوقات في هذه الآيات لعلة؛ اذكرها.\nوَجَعَلۡنَا نَوۡمَكُمۡ سُبَاتٗا ٩\nأي راحة لكم، وقطعًا لأشغالكم، التي متى تمادت بكم أضرت بأبدانكم، فجعل الله الليل والنوم يغشى الناس لتنقطع حركاتهم الضارة، وتحصل راحتهم النافعة. السعدي: ٩٠٦.\nما وجه كون النوم نعمةً يمتنُّ الله بها على عباده؟\nإِنَّ جَهَنَّمَ كَانَتۡ مِرۡصَادٗا ٢١\nيعني: أنه لا يدخل أحد الجنة حتى يجتاز بالنار، فإن كان معه جواز نجا، وإلا احتبس. ابن كثير: ٤/٤٦٤.\nما الذي يفهم من كون جهنم مرصادًا؟\nوَكُلَّ شَيۡءٍ أَحۡصَيۡنَٰهُ كِتَٰبٗا ٢٩\nكل شيءٍ من قليل وكثير ﴿أَحۡصَيۡنَٰهُ كِتَٰبًا﴾ أي: كتبناه في اللوح المحفوظ، فلا يخشى المجرمون أنا عذبناهم بذنوب لم يعملوها، ولا يحسبوا أنه يضيع من أعمالهم شيء، أو ينسى منها مثقال ذرة. السعدي: ٩٠٧\nما الحكمة من كتابة أعمال العباد؟\nفَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا ٣٠\nعن عبد الله بن عمرو، قال: \"لم تنزل على أهل النار آية أشد من هذه: ﴿فَذُوقُواْ فَلَن نَّزِيدَكُمۡ إِلَّا عَذَابًا﴾؛ قال: فهم في مزيد من العذاب أبدًا\". الطبري: ٢٤/١٦٩.\nما أشد آية في القرآن على أهل النار؟ ولماذا؟"],[583,"§النبإ ، النازعات\nwords\nمَفَازًافَوزًا بِدُخُولِهِمُ الجَنَّةَ، أَو مَكَانًا يَفُوزُونَ بِهِ؛ وَهُوَ الجَنَّةُ.\nوَكَوَاعِبَحَدِيثَاتِ السِّنِّ، نَوَاهِدَ.\nدِهَاقًامَملُوءَةً خَمرًا.\nمَآبًامرجِعًا بِالعَمَلِ الصَّالِحِ.\nوَالنَّاشِطَاتِقَسَمٌ بِالمَلاَئِكَةِ تَسُلُّ أَروَاحَ المُؤمِنِينَ بِرِفقٍ.\nوَالسَّابِحَاتِقَسَمٌ بِالمَلاَئِكَةِ الَّتِي تَسبَحُ فِي نُزُولِهَا مِنَ السَّمَاءِ، وَصُعُودِها إِلَيهَا.\nفَالسَّابِقَاتِقَسَمٌ بِالمَلاَئِكَةِ الَّتِي تَسبِقُ الشَّيَاطِينَ بِالوَحيِ إِلَى الأَنبِيَاءِ؛ لِئَلاَّ تَستَرِقهُ.\nتَتبَعُهَا الرَّادِفَةُتَلِيهَا نَفخَةٌ أُخرَى لِلبَعثِ.\ndeeds\nفي يومك اعمل ثلاثة أعمال تدل على التقوى؛ كالصوم، ترك المعصية خوف عقاب الله تعالى واستحياء منه، الصدقة، الإحسان إلى الناس، إدخال السرور على قلب مسلم.\nاستعذ بالله من سوء الخاتمة.\nسَلِ الله تعالى حسن الخاتمة عند الموت، وتذكر.\nguid\nفضيلة التقوى وعِظَم ما أعد الله لأهلها.\nتعظيم الله تعالى حق تعظيمه.\nقرب يوم القيامة؛ فكل ما هو آت قريب.\nrefl\nلَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّٰبٗا ٣٥\nقوله: ﴿لَّا يَسۡمَعُونَ فِيهَا لَغۡوًا وَلَا كِذَّٰبًا﴾ كقوله: ﴿لَّا لَغۡوٌ فِيهَا وَلَا تَأۡثِيمٌ﴾ [الطور: ٢٣]؛ أي: ليس فيها كلام لاغٍ عارٍ عن الفائدة، ولا إثم كذب؛ بل هي دار السلام، وكل ما فيها سالم من النقص. ابن كثير: ٤/٤٦٥.\nذكرت الآية نوعًا من النعيم المعنوي في الجنة؛ وضحه.\nلَّا يَسۡمَعُونَ فِيهَا لَغۡوٗا وَلَا كِذَّٰبٗا ٣٥\nفلما أحاط بأهل جهنم أشدُّ الأذى بجميع حواسهم؛ من جراء حرق النار وسقيهم الحميم والغساق؛ لينال العذاب بواطنهم كما نال ظاهر أجسادهم، كذلك نفى عن أهل الجنة أقل الأذى؛ وهو أذى سماع ما يكرهه الناس؛ فإن ذلك أقل الأذى. ابن عاشور: ٣٠/٤٦.\nما مناسبة نفي سماع اللغو والكذاب عن أهل الجنة لما قبلها من آيات السورة الكريمة؟\nإِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ٤٠\nالكافر يقول ذلك يوم القيامة؛ حين لا تُقبل توبة، ولا تنفع حسنة. وأمَّا من يقول ذلك في الدنيا فهذا يقوله في دار العمل على وجه الخشية لله، فيُثاب على خوفه من الله؛ وقد قالت مريم: ﴿يَٰلَيۡتَنِي مِتُّ قَبۡلَ هَٰذَا وَكُنتُ نَسۡيٗا مَّنسِيّٗا﴾ [مريم: ٢٣]؛ ولم يكن هذا كتمني الموت يوم القيامة. ابن تيمية: ٦/٤٥٦.\nما الفرق بين الندم على المعصية في الدنيا والندم عليها في الآخرة؟\nإِنَّآ أَنذَرۡنَٰكُمۡ عَذَابٗا قَرِيبٗا يَوۡمَ يَنظُرُ ٱلۡمَرۡءُ مَا قَدَّمَتۡ يَدَاهُ وَيَقُولُ ٱلۡكَافِرُ يَٰلَيۡتَنِي كُنتُ تُرَٰبَۢا ٤٠\nعن أبي هريرة وابن عمر -رضي الله عنهم- أن الله تعالى يقتص يوم البعث للبهائم؛ بعضها من بعض، ثم يقول لها: كوني ترابًا فتكون؛ فيتمنى الكافر مثل ذلك. فقد عُلِم أن ذلك اليوم في غاية العظمة، وأنه لا بد من كونه. البقاعي: ٢١/٢١٦.\nمتى يتمنى الكافر أن يكون ترابًا؟ ولماذا يتمنى ذلك؟\nوَٱلنَّٰشِطَٰتِ نَشۡطٗا ٢\nقال بعض السلف إن الملائكة يسُلُّون أرواح المؤمنين سلًّا رقيقًا، ثم يتركونها حتى تستريح رويدًا ثم يستخرجونها برفق ولطف؛ كالذي يسبح في الماء؛ فإنه يتحرك برفق لئلَّا يغرق؛ فهم يرفقون في ذلك الاستخراج لئلَّا يصل إلى المؤمن ألم وشدة. الألوسي: ٣٠/٢٣.\nبيّن كيف تقبض الملائكة أرواح المؤمنين، ولماذا؟\nقُلُوبٞ يَوۡمَئِذٖ وَاجِفَةٌ ٨ أَبۡصَٰرُهَا خَٰشِعَةٞ ٩\n﴿أَبۡصَٰرُهَا خَٰشِعَةٌ﴾: كناية عن الذل والخوف. ابن جزي: ١/٢٥٤٥.\nعلى ماذا يدل وصف الأبصار بالخشوع في هذه الآية؟\nهَلۡ أَتَىٰكَ حَدِيثُ مُوسَىٰٓ ١٥\nوهذا تسلية للنبي؛ أي: إن فرعون كان أقوى من كفار عصرك ثم أخذناه، وكذلك هؤلاء. القرطبي: ٢٢/٥٣.\nلماذا قص الله على نبيه قصة موسى -عليه السلام- مع فرعون؟"],[584,"§النازعات\nwords\nتَزَكَّىتَتَطَهَّرَ مِنَ الكُفرِ، وَتَتَحَلَّى بِالإِيمَانِ.\nوَأَهدِيَكَأُرشِدَكَ.\nنَكَالَعُقُوبَةَ.\nرَفَعَ سَمكَهَاأَعلَى سَقفَهَا.\nوَأَغطَشَ لَيلَهَاأَظلَمَ لَيلَهَا بِغُرُوبِ شَمسِهَا.\nوَأَخرَجَ ضُحَاهَاأَبرَزَ نَهَارَهَا بِشُرُوقِ شَمسِهَا.\nدَحَاهَابَسَطَهَا، وَأَودَعَ فِيهَا مَنَافِعَهَا.\nالطَّامَّةُالقِيَامَةُ، وَهِيَ النَّفخَةُ الثَّانِيَةُ.\nوَبُرِّزَتِأُظهِرَت إِظهَارًا بَيِّنًا.\nأَيَّانَ مُرسَاهَامَتَى وَقتُ حُلُولِهَا؟\nعَشِيَّةًمَا بَينَ الظُّهرِ إِلَى غُرُوبِ الشَّمسِ.\ndeeds\nدعوة غير مسلم إلى الإسلام بأسلوب حكيم.\nاعمل عملًا صالحًا تتمنى أن تتذكره يوم القيامة.\nحاسب نفسك قبل النوم.\nguid\nحسن الأسلوب ولينه في الدعوة.\nدعوة أي شخص مهما بلغ طغيانه.\nعِظَم منزلة المراقبة.\nrefl\nفَقُلۡ هَل لَّكَ إِلَىٰٓ أَن تَزَكَّىٰ ١٨\nحَثُّهُ على أن يستعد لتخليص نفسه من العقيدة الضالة، التي هي خبث مجازي في النفس، فيقبَلَ إرشاد من يرشده إلى ما به زيادة الخير. ابن عاشور: ٣٠/٧٧.\nما فائدة أمر موسى -عليه السلام- لفرعون بالتزكي في أول دعوته له؟\nوَأَهۡدِيَكَ إِلَىٰ رَبِّكَ فَتَخۡشَىٰ ١٩\nوتفريع (فتخشى) على (وأهديك) إشارة إلى أن خشية الله لا تكون إلا بالمعرفة؛ قال تعالى: ﴿يَخۡشَى ٱللَّهَ مِنۡ عِبَادِهِ ٱلۡعُلَمَٰٓؤُاْ﴾ [فاطر: ٢٨] أي: العلماء به؛ أي: يخشاه خشية كاملة لا خطأ فيها ولا تقصير. ابن عاشور: ٣٠/٧٧.\nلماذا جاءت الخشية بعد الهداية في الآية الكريمة؟\nإِنَّ فِي ذَٰلِكَ لَعِبۡرَةٗ لِّمَن يَخۡشَىٰٓ ٢٦\nفإن من يخشى الله هو الذي ينتفع بالآيات والعبر، فإذا رأى عقوبة فرعون عرف أن كل من تكبر وعصى وبارز الملك الأعلى عاقبه في الدنيا والآخرة، وأمَّا من ترحلت خشية الله من قلبه فلو جاءته كل آية لم يؤمن بها. السعدي: ٩٠٩.\nمن الذي ينتفع بالعظات القرآنية ومن لا ينتفع؟\nءَأَنتُمۡ أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ بَنَىٰهَا ٢٧ رَفَعَ سَمۡكَهَا فَسَوَّىٰهَا ٢٨ وَأَغۡطَشَ لَيۡلَهَا وَأَخۡرَجَ ضُحَىٰهَا ٢٩ وَٱلۡأَرۡضَ بَعۡدَ ذَٰلِكَ دَحَىٰهَآ ٣٠ أَخۡرَجَ مِنۡهَا مَآءَهَا وَمَرۡعَىٰهَا ٣١ وَٱلۡجِبَالَ أَرۡسَىٰهَا ٣٢ مَتَٰعٗا لَّكُمۡ وَ لِأَنۡعَٰمِكُمۡ ٣٣\nيقول تعالى مبينًا دليلًا واضحًا لمنكري البعث ومستبعدي إعادة الله للأجساد: (أأنتم) أيها البشر ﴿أَشَدُّ خَلۡقًا أَمِ ٱلسَّمَآءُۚ﴾... فالذي خلق السماوات العظام وما فيها من الأنوار والأجرام، والأرض الكثيفة الغبراء وما فيها من ضروريات الخلق ومنافعهم لا بد أن يبعث الخلق المكلفين فيجازيهم على أعمالهم؛ فمن أحسن فله الحسنى، ومن أساء فلا يلومن إلا نفسه؛ ولهذا ذكر بعد هذا قيام الساعة ثم الجزاء. السعدي: ٩٠٩.\nعلى ماذا تدل هذه الآيات العظام التي ذكرها -سبحانه وتعالى-؟ ولماذا أعقب بذكر الجزاء بعد ذكر هذه الآيات؟\nوَبُرِّزَتِ ٱلۡجَحِيمُ لِمَن يَرَىٰ ٣٦\nالظاهر أن تبرز لكل راءٍ؛ فأما المؤمن فيعرف برؤيتها قدر نعمة الله عليه بالسلامة منها، وأمَّا الكافر فيزداد غمًّا إلى غمه وحسرة إلى حسرته. الشوكاني: ٥/٣٨٠.\nهل تبرز الجحيم للمؤمنين والكفار أو للكفار فقط؟ ولماذا؟\nوَأَمَّا مَنۡ خَافَ مَقَامَ رَبِّهِۦ وَنَهَى ٱلنَّفۡسَ عَنِ ٱلۡهَوَىٰ ٤٠ فَإِنَّ ٱلۡجَنَّةَ هِيَ ٱلۡمَأۡوَىٰ ٤١\nوأصل الهوى: مطلق الميل، وشاع في الميل إلى الشهوة، وسُمِّي بذلك -على ما قال الراغب- لأنه يهوي بصاحبه في الدنيا إلى كل واهية، وفي الآخرة إلى الهاوية؛ ولذلك مُدح مخالفه. قال بعض الحكماء: \"إذا أردت الصواب فانظر هواك فخالفه\". وقال الفضيل: \"أفضل الأعمال مخالفة الهوى\". الألوسي: ٣/٣٦.\nلماذا سُمي الهوى بذلك؟\nإِنَّمَآ أَنتَ مُنذِرُ مَن يَخۡشَىٰهَا ٤٥\nأي: إنَّما بعثت لتنذر بها، وليس عليك الإخبار بوقتها، وخص الإنذار ب(من يخشاها)؛ لأنه هو الذي ينفعه الإنذار. ابن جزي: ٢/٥٣٥.\nمن الذي ينفعه الإنذار؟"],[585,"§عبس\nwords\nسَفَرَةٍمَلاَئِكَةٍ كَتَبَةٍ، يَقُومُونَ بِالسِّفَارَةِ بَينَ اللهِ وَخَلقِهِ.\nنُطفَةٍمَاءٍ قَلِيلٍ مَهِينٍ؛ وَهُوَ المَنِيُّ.\nفَقَدَّرَهُخَلَقَهُ أَطوَارًا.\nأَنشَرَهُأَحيَاهُ.\nوَقَضبًاعَلَفًا لِلدَّوَابِّ.\nغُلبًاعَظِيمَةَ الأَشجَارِ.\nوَأَبًّاكَلأً لِلبَهَائِمِ.\ndeeds\nزُر اليوم معوقًا أو ضعيفًا محاولًا إدخال الأنس على نفسه.\nحدد أحد أوقات الإجابة وأكثر من الدعاء بالهداية والمغفرة لأهل بيتك.\nاختر واحدًا من أصناف طعامك اليوم وتأمل خلق الله له من بدايته إلى أن وصلك، ثم احمد الله تعالى.\nguid\nبقاء معاتبة الله تعالى لنبيه تتلى قرآنًا هو من أعظم الأدلة على صدق النبي -صلى الله عليه وسلم- وأن القرآن الكريم من عند الله.\nشكر الله تعالى على تنويع النعم.\nالاستعداد ليوم القيامة.\nrefl\nعَبَسَ وَتَوَلَّىٰٓ ١ أَن جَآءَهُ ٱلۡأَعۡمَىٰ ٢ وَمَا يُدۡرِيكَ لَعَلَّهُۥ يَزَّكَّىٰٓ ٣ أَوۡ يَذَّكَّرُ فَتَنفَعَهُ ٱلذِّكۡرَىٰٓ ٤ أَمَّا مَنِ ٱسۡتَغۡنَىٰ ٥ فَأَنتَ لَهُۥ تَصَدَّىٰ ٦ وَمَا عَلَيۡكَ أَلَّا يَزَّكَّىٰ ٧ وَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ٨ وَهُوَ يَخۡشَىٰ ٩ فَأَنتَ عَنۡهُ تَلَهَّىٰ ١٠\nهذه فائدة كبيرة هي المقصودة من بعثة الرسل، ووعظ الوعاظ، وتذكير المذكرين؛ فإقبالك على من جاء بنفسه مفتقرًا لذلك منك هو الأليق الواجب، وأمَّا تصديك وتعرضك للغني المستغني الذي لا يسأل ولا يستفتي لعدم رغبته في الخير مع تركك من هو أهم منه، فإنه لا ينبغي لك؛ فإنه ليس عليك أن لا يَزَّكَّى، فلو لم يَتَزَكَّ فلست بمحاسب على ما عمله من الشر. فدل هذا على القاعدة: \"أنه لا يترك أمر معلوم لأمر موهوم، ولا مصلحة متحققة لمصلحة متوهمة\". السعدي: ٩١١.\nفي الآيات فائدة للداعية في مراعاة الأولويات في دعوته لله؛ وضّح ذلك\nوَأَمَّا مَن جَآءَكَ يَسۡعَىٰ ٨ وَهُوَ يَخۡشَىٰ ٩ فَأَنتَ عَنۡهُ تَلَهَّىٰ ١٠\nالممنوع عنه في الحقيقة الإعراض عمن أسلم، لا الإقبال على غيره والاهتمام بأمره حرصًا على -صلى الله عليه وسلم- إسلامه. الألوسي: ١٥/٢٤٣.\nما الممنوع في قصة ابن أم مكتوم حينما أقبل على النبي -صلى الله عليه وسلم- يريد الهداية؟\nكَلَّآ إِنَّهَا تَذۡكِرَةٞ ١١ فَمَن شَآءَ ذَكَرَهُۥ ١٢ فِي صُحُفٖ مُّكَرَّمَةٖ ١٣ مَّرۡفُوعَةٖ مُّطَهَّرَةِۢ ١٤ بِأَيۡدِي سَفَرَةٖ ١٥ كِرَامِۢ بَرَرَةٖ ١٦\n﴿كَلَّآ إِنَّهُۥ تَذۡكِرَةٌ﴾ يعني: القرآن. ﴿بِأَيۡدِي سَفَرَةٍ كِرَامِۭ بَرَرَةٍ﴾ أي: خَلقُهم كريم حسن شريف، وأخلاقهم وأفعالهم بارة طاهرة كاملة. ومن هاهنا ينبغي لحامل القرآن أن يكون في أفعاله وأقواله على السداد والرشاد. ابن كثير: ٤/٤٧٢.\nوصف الله الملائكة الموكلة بصحف القرآن بأوصاف؛ كيف يستفيد حافظ القرآن وحامله من هذه الأوصاف؟\nمِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ١٨ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ١٩\nأي: من أي شيء خلق الله هذا الكافر فيتكبر؟! أي: اعجبوا لخلقه. ﴿مِن نُّطۡفَةٍ﴾ أي: من ماء يسير مهين جماد خلقه، فلِمَ يغلط في نفسه؟! قال الحسن: \"كيف يتكبر من خرج من سبيل البول مرتين؟!\". القرطبي: ٢٢/٧٩.\nلماذا لا يحق لابن آدم أن يتكبر؟\nثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ٢١\nأي أكرمه بالدفن، ولم يجعله كسائر الحيوانات التي تكون جيفها على وجه الأرض. السعدي: ٩١١.\nكيف يكون الإقبار نعمة يمتن الله بها على عباده؟\nمِنۡ أَيِّ شَيۡءٍ خَلَقَهُۥ ١٨ مِن نُّطۡفَةٍ خَلَقَهُۥ فَقَدَّرَهُۥ ١٩ ثُمَّ ٱلسَّبِيلَ يَسَّرَهُۥ ٢٠ ثُمَّ أَمَاتَهُۥ فَأَقۡبَرَهُۥ ٢١\nفقد عرف بهذا أن أول الإنسان نطفة مذرة، وآخره جيفة قذرة، وهو فيما بين ذلك يحمل العذرة؛ فما شرَّفَه بالعلم إلا الذي أبدعه وصوره، وذلك موجب لأن يشكره لا أن يكفره. البقاعي: ٢١/٢٦٢.\nبماذا يشرف الإنسان ويرتفع قدره؟\nفَلۡيَنظُرِ ٱلۡإِنسَٰنُ إِلَىٰ طَعَامِهِۦٓ ٢٤\nأمر بالاعتبار في الطعام؛ كيف خلقه الله بقدرته، ويسره برحمته؛ فيجب على العبد طاعته وشكره، ويقبح معصيته والكفر به. ابن جزي: ٢/٥٣٨.\nما العبرة التي يفيدها العبد عند النظر لمخلوقات الله؟"],[586,"§التكوير ، عبس\nwords\nقَتَرَةٌذِلَّةٌ، وَظُلمَةٌ.\nانكَدَرَتتَنَاثَرَت، وَذَهَبَ نُورُهَا.\nالعِشَارُالنُّوقُ الحَوَامِلُ.\nعُطِّلَتأُهمِلَت وَتُرِكَت.\nسُجِّرَتمُلِئَت حَتَّى فَاضَت، فَانفَجَرَت، ثُمَّ اتَّقَدَت نِيرَانًا.\nالمَوءُودَةُالطِّفلَةُ المَدفُونَةُ حَيَّةً.\nكُشِطَتقُلِعَت وَأُزِيلَت.\nأُزلِفَتقُرِّبَت مِن أَهلِهَا.\ndeeds\nاعطف على من هو أصغر منك.\nاعمل اليوم عملًا صالحًا تتمنى أن تراه حاضرًا أمامك يوم القيامة.\nسل الله الاستقامة.\nguid\nتذكَّر يوم الحساب واستعدَّ له.\nتكريم الله للملائكة يدعو العبد لمحبتهم والإيمان بهم.\nالنبي لا يعلم الغيب، ومن كان دونه فمن باب أولى.\nrefl\nوَوُجُوهٞ يَوۡمَئِذٍ عَلَيۡهَا غَبَرَةٞ ٤٠ تَرۡهَقُهَا قَتَرَةٌ ٤١ أُوْلَٰٓئِكَ هُمُ ٱلۡكَفَرَةُ ٱلۡفَجَرَةُ ٤٢\nأي الذين خرجوا عن دائرة الشرع خروجًا فاحشًا حتى كانوا عريقين في ذلك الكفر والفجور، وهم في الأغلب المترفون الذين يحملهم غناهم على التكبر والأشر والبطر؛ فلجمعهم بين الكفر والفجور جمع لهم بين الغبرة والقترة. البقاعي: ٢١/٢٧٣.\nلماذا جمع للكفرة الفجرة بين الغبرة والقترة؟\nإِذَا ٱلشَّمۡسُ كُوِّرَتۡ ١ وَإِذَا ٱلنُّجُومُ ٱنكَدَرَتۡ ٢ وَإِذَا ٱلۡجِبَالُ سُيِّرَتۡ ٣ وَإِذَا ٱلۡعِشَارُ عُطِّلَتۡ ٤ وَإِذَا ٱلۡوُحُوشُ حُشِرَتۡ ٥ وَإِذَا ٱلۡبِحَارُ سُجِّرَتۡ ٦ وَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ٧ وَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ٨ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ٩ وَإِذَا ٱلصُّحُفُ نُشِرَتۡ ١٠ وَإِذَا ٱلسَّمَآءُ كُشِطَتۡ ١١ وَإِذَا ٱلۡجَحِيمُ سُعِّرَتۡ ١٢ وَإِذَا ٱلۡجَنَّةُ أُزۡلِفَتۡ ١٣ عَلِمَتۡ نَفۡسٞ مَّآ أَحۡضَرَتۡ ١٤\nهذه الأوصاف التي وصف الله بها يوم القيامة من الأوصاف التي تنزعج لها القلوب، وتشتد من أجلها الكروب، وترتعد الفرائص، وتعم المخاوف، وتحث أولي الألباب للاستعداد لذلك اليوم، وتزجرهم عن كل ما يوجب اللوم. السعدي: ٩١٢.\nما الفائدة العملية التي تفيدها من قراءة هذه الآيات؟\nوَإِذَا ٱلنُّفُوسُ زُوِّجَتۡ ٧\nقُرِنَ كل صاحب عمل بشكله ونظيره؛ فقُرِنَ بين المتحابين في الله في الجنة، وقُرِنَ بين المتحابين في طاعة الشيطان في الجحيم؛ فالمرء مع من أحب شاء أو أبى. ابن القيم: ٣/٢٥٧.\nمحبتك للآخرين لها آثار كبيرة يوم القيامة؛ وضّح ذلك.\nوَإِذَا ٱلۡمَوۡءُۥدَةُ سُئِلَتۡ ٨ بِأَيِّ ذَنۢبٖ قُتِلَتۡ ٩\nإشعار بأنه لا ذنب لها فتقتل بسببه، بل الجرم على قاتلها؛ ولكن لعظم الجرم يتوجه السؤال إليها تبكيتًا لوائدها. الشنقيطي: ٨/٤٣٨.\nالموؤودة لا ذنب لها فكيف يوجه إليها السؤال؟\nإِنَّهُۥ لَقَوۡلُ رَسُولٖ كَرِيمٖ ١٩ ذِي قُوَّةٍ عِندَ ذِي ٱلۡعَرۡشِ مَكِينٖ ٢٠ مُّطَاعٖ ثَمَّ أَمِينٖ ٢١\nهذا كله يدل على شرف القرآن عند الله تعالى، بأنه بعث به هذا الملك الكريم، الموصوف بتلك الصفات الكاملة، والعادة أن الملوك لا ترسل الكريم عليها إلا في أهم المهمات وأشرف الرسائل. السعدي: ٩١٣.\nتدبر منزلة القرآن الكريم عند الله من خلال صفات الملك الذي أوحاه إلى نبيه.\nوَمَا هُوَ بِقَوۡلِ شَيۡطَٰنٖ رَّجِيمٖ ٢٥ فَأَيۡنَ تَذۡهَبُونَ ٢٦ إِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٢٧\nفمن علم هذه الأوصاف للقرآن والرسولين الآتيين به: الملكي والبشري؛ أحبه وأحبهما، وبالغ في التعظيم والإجلال، وأقبل على تلاوته في كل أوقاته، وبالغ في السعي في كل ما يأمر به والهرب مما ينهى عنه، ليحصل له الاستقامة رغبة في مرافقة من أتى به ورؤية من أتى من عنده. البقاعي: ٢١/٢٩٤.\nما الذي تثمره معرفة أوصاف القرآن وأوصاف مَن بلَّغَنَا إياه؟\nإِنۡ هُوَ إِلَّا ذِكۡرٞ لِّلۡعَٰلَمِينَ ٢٧ لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ ٢٨\nهذا القرآن ذكر لجميع الناس يتذكرون به ويتعظون: ﴿إِنۡ هُوَ إِلَّا ذِكۡرٌ لِّلۡعَٰلَمِينَ لِمَن شَآءَ مِنكُمۡ أَن يَسۡتَقِيمَ﴾ أي: من أراد الهداية فعليه بهذا القرآن؛ فإنه منجاة له وهداية، ولا هداية فيما سواه. ابن كثير: ٤/٤٨١.\nتحاول البشرية اليوم إيجاد طريقٍ سوي ينقذها من تخبطاتها في ظلمات الضلالات والجهل؛ فما الطريق الوحيد للنجاة والهداية؟"],[587,"§الانفطار ، المطففين\nwords\nانفَطَرَتانشَقَّت.\nانتَثَرَتتَسَاقَطَت.\nفُجِّرَتامتَلَأَت، وَفَاضَت، فَانفَجَرَت، وَسَالَت مِيَاهُهَا.\nبُعثِرَتقُلِبَت بِبَعثِ مَن كَانَ مَقبُورًا فِيهَا.\nمَا غَرَّكَ بِرَبِّكَمَا خَدَعَكَ وَجَرَّأَكَ عَلَى الكُفرِ بِهِ وَعِصيَانِهِ؟\nفَسَوَّاكَجَعَلَكَ مُستَوِيَ الخِلقَةِ سَالِمَ الأَعضَاءِ.\nفَعَدَلَكَجَعَلَكَ مُعتَدِلَ الخَلقِ مُتَنَاسِبَ الأَعضَاءِ.\nلَحَافِظِينَلَمَلاَئِكَةً رُقَبَاءَ يَكتُبُونَ أَعمَالَكُم.\nبِغَائِبِينَفَلاَ يَخرُجُونَ مِن جَهَنَّمَ وَلاَ يَمُوتُونَ.\nلِلمُطَفِّفِينَالَّذِينَ يَبخَسُونَ المِكيَالَ وَالمِيزَانَ.\ndeeds\nزُر القبور.\nاشكر الله تعالى على حسن خلقتك.\nتذكر ذنبًا فعلته واستغفر الله منه.\nguid\nالمبادرة بالأعمال الصالحة وعدم الاغترار بكرم الله وحلمه.\nمن نعم الله على الإنسان إحسان خلقته.\nكل عمل تعمله هو مسجل إما لك أو عليك.\nrefl\nيَٰٓأَيُّهَا ٱلۡإِنسَٰنُ مَا غَرَّكَ بِرَبِّكَ ٱلۡكَرِيمِ ٦\nالتعبير بالرب مع دلالته على الإحسان يدل على الانتقام عند الإمعان في الإجرام؛ لأن ذلك شأن المربي، فكان ذلك مانعًا من الاغترار لمن تأمل. البقاعي: ٢١/٣٠٢.\nما دلالة التعبير بالرب في الآية؟\nوَإِنَّ عَلَيۡكُمۡ لَحَٰفِظِينَ ١٠ كِرَامٗا كَٰتِبِينَ ١١ يَعۡلَمُونَ مَا تَفۡعَلُونَ ١٢\nقد أقام الله عليكم ملائكة كرامًا يكتبون أقوالكم وأفعالكم، ويعلمون أفعالكم،... فاللائق بكم أن تكرموهم وتجلوهم وتحترموهم. السعدي: ٩١٤.\nما شعورك تجاه الملائكة الذين يسجلون أعمالك؟ وإلى ماذا يدفعك هذا الشعور؟\nإِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ١٣\nفهؤلاء جزاؤهم النعيم في القلب والروح والبدن في دار الدنيا، وفي دار البرزخ، وفي دار القرار. السعدي: ٩١٤.\nالطاعة تورث النعيم والسعادة في ثلاث مراحل يمر بها الإنسان؛ فما هي؟\nإِنَّ ٱلۡأَبۡرَارَ لَفِي نَعِيمٖ ١٣ وَإِنَّ ٱلۡفُجَّارَ لَفِي جَحِيمٖ ١٤\nلا تحسب أن الآية مقصورةٌ على نعيم الآخرة وجحيمها فقط، بل في دورهم؛ أعني: دار الدنيا، ودار البرزخ، ودار القرار؛ فهؤلاء في نعيم، وهؤلاء في جحيم، وهل النعيمُ إلا نعيم القلب؟! وهل العذاب إلا عذاب القلب؟! وأي عذابٍ أشد من الخوف والهم والحزن، وضيق الصدر، وإعراضه عن الله والدار الآخرة، وتعلقه بغير الله، وانقطاعه عن الله؛ بكل وادٍ منه شعبة؟! وكل من تعلق به وأحبه من دون الله فإنه يسومه سوء العذاب. ابن القيم: ٣/٢٦٧.\nفي أي دار يكون النعيم والجحيم المذكوران في الآية؟\nوَيۡلٞ لِّلۡمُطَفِّفِينَ ١\nوالتقديم في افتتاحية هذه السورة بالويل للمطففين يشعر بشدة خطر هذا العمل، وهو فعلًا خطير؛ لأنه مقياس اقتصاد العالم وميزان التعامل، فإذا اختل أحدث خللًا في اقتصاده، وبالتالي اختلال في التعامل، وهو فساد كبير. الشنقيطي: ٨/٤٥٤.\nما الفائدة في افتتاح هذه السورة بالويل للمطففين؟\nوَيۡلٞ لِّلۡمُطَفِّفِينَ ١ ٱلَّذِينَ إِذَا ٱكۡتَالُواْ عَلَى ٱلنَّاسِ يَسۡتَوۡفُونَ ٢ وَإِذَا كَالُوهُمۡ أَو وَّزَنُوهُمۡ يُخۡسِرُونَ ٣\nوفي ذلك تنبيه على أن أصل الآفات الخلق السيِّئ، وهو حب الدنيا الموقع في جَمعِ الأموال من غير وجهها؛ ولو بأخس الوجوه: التطفيف الذي لا يرضاه ذو مروءة؛ وهم من يقاربون ملء الكيل وعدل الوزن ولا يملؤون ولا يعدلون. البقاعي: ٢١/٣١١.\nما أصل الآفات وما علاقته بالتطفيف؟\nأَلَا يَظُنُّ أُوْلَٰٓئِكَ أَنَّهُم مَّبۡعُوثُونَ ٤ لِيَوۡمٍ عَظِيمٖ ٥ يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ ٦\nوفي هذا الإنكار والتعجيب، وكلمة الظن، ووصف اليوم بالعظيم، وقيام الناس فيه لله خاضعين، ووصف ذاته برب العالمين: بيان بليغ لعظم الذنب وتفاقم الإثم في التطفيف. القرطبي: ٢٢/١٣٦.\nإلى أي حد عظم الله تعالى ذنب التطفيف؟"],[588,"§المطففين\nwords\nسِجِّينٍسِجنٍ، وَضِيقٍ.\nمَرقُومٌمَكتُوبٌ كَالرَّقمِ فِي الثَّوبِ لاَ يُمحَى.\nأَسَاطِيرُأَبَاطِيلُ.\nرَانَغَطَّى.\nالأَرَائِكِالأَسِرَّةِ المُزَيَّنَةِ بِالسُّتُورِ وَالثِّيَابِ.\nرَحِيقٍخَمرٍ صَافِيَةٍ.\nوَمِزَاجُهُخَلطُهُ.\nتَسنِيمٍعَينٍ فِي أَعلَى الجَنَّةِ.\nيَشرَبُ بِهَايَشرَبُونَ مُتَلَذِّذِينَ بِهَا.\ndeeds\nقل: \"اللهم إني أسألك لذة النظر إلى وجهك الكريم؛ في غير ضراء مضرة، ولا فتنة مضلة\".\nتصدق بسقاية مسلم.\nانظر إلى رجل يبكر في الحضور إلى المسجد ونافسه في ذلك.\nguid\nمن أعظم العقوبات: الحرمان من النظر إلى الرب -تبارك وتعالى- في الآخرة.\nالذنوب هي سبب الران على القلب.\nمن صفات المؤمنين التنافس في الطاعات.\nrefl\nكَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ١٤\nهو الذنب على الذنب حتى يسود القلب؛ قال مجاهد: \"هو الرجل يذنب الذنب فيحيط الذنب بقلبه، ثم يذنب الذنب فيحيط الذنب بقلبه؛ حتى تغشى الذنوب قلبه\"... قال بكر بن عبد الله: \"إن العبد إذا أذنب صار في قلبه كوخزة الإبرة، ثم إذا أذنب ثانيًا صار كذلك، ثم إذا كثرت الذنوب صار القلب كالمنخل أو كالغربال؛ لا يعي خيرًا ولا يثبت فيه صلاح\". القرطبي: ٢٢/١٤٣.\nما الران؟ وكيف يصل إلى قلب العبد؟\nكَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ ١٤\nعن أبي هريرة، قال: قال رسول الله -صلى الله عليه وسلم-: «إذا أذنب العبد نكت في قلبه نكتة سوداء؛ فإن تاب صقل منها، فإن عاد عادت حتى تعظم في قلبه. فذلك الران الذي قال الله: ﴿كَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾». الطبري: ٢٤/٢٨٦.\nوضح أثر التوبة على الران الذي يصيب القلب.\nكَلَّآ إِنَّهُمۡ عَن رَّبِّهِمۡ يَوۡمَئِذٖ لَّمَحۡجُوبُونَ ١٥\nقال الحسين بن الفضل: \"كما حجبهم في الدنيا عن توحيده حجبهم في الآخرة عن رؤيته\". قال الزجاج: \"في هذه الآية دليل على أن الله -عز وجل- يُرى في القيامة\". الشوكاني: ٥/٤٠٠.\nلماذا حُجِب الفجار عن رؤية الله في الآخرة؟\nخِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ٢٦\n(المتنافسون) أي: الراغبون في المبادرة إلى طاعة الله تعالى. وأصل التنافس التغالب في الشيء النفيس، ومجاهدة النفس للتشبه بالأفاضل واللحوق بهم من غير إدخال ضرر على غيره. وهي بهذا المعنى من شرف النفس وعلو الهمة. الألوسي: ١٥/٢٨٣.\nما التنافس المحمود المقصود في الآية؟\nخِتَٰمُهُۥ مِسۡكٞۚ وَفِي ذَٰلِكَ فَلۡيَتَنَافَسِ ٱلۡمُتَنَٰفِسُونَ ٢٦\nوفي هذه الآية الكريمة لفت لأول السورة: إذا كان أولئك يسعون لجمع المال بالتطفيف؛ فلهم الويل يوم القيامة. وإذا كان الأبرار لفي نعيم يوم القيامة، وهذا شرابهم؛ فهذا هو محل المنافسة، لا في التطفيف من الحب أو أي مكيل أو موزون. الشنقيطي: ٨/٤٦٣.\nما المنافسة المحمودة والمذمومة في السورة؟\nوَمِزَاجُهُۥ مِن تَسۡنِيمٍ ٢٧ عَيۡنٗا يَشۡرَبُ بِهَا ٱلۡمُقَرَّبُونَ ٢٨\nوالتسنيم أعلى أشربة الجنة؛ فأخبر سبحانه أن مزاج شراب الأبرار من التسنيم، وأن المقربين يشربون منه بلا مزاج...؛ وهذا لأن الجزاء وفاق العمل، فكما خلصت أعمال المقربين كلها لله خلص شرابهم، وكما مزج الأبرار الطاعات بالمباحات مزج لهم شرابهم. فمن أَخلَصَ أُخلِص شرابه، ومن مَزَج مُزِج شرابُه. ابن القيم: ٣/٢٧٠.\nلماذا كان شراب المقربين خالصًا من تسنيم، وشراب الأبرار ممزوجًا بغيره؟\nوَإِذَا ٱنقَلَبُوٓاْ إِلَىٰٓ أَهۡلِهِمُ ٱنقَلَبُواْ فَكِهِينَ ٣١\nأي: مسرورين مغتبطين؛ وهذا من أعظم ما يكون من الاغترار: أنهم جمعوا بين غاية الإساءة والأمن في الدنيا، حتى كأنهم قد جاءهم كتاب من الله وعهد أنهم أهل السعادة، وقد حكموا لأنفسهم أنهم أهل الهدى، وأن المؤمنين ضالون؛ افتراء على الله، وتجرؤوا على القول عليه بلا علم. السعدي: ٩١٦.\nبَيِّن وجه الإساءة العظيم الذي بينه الله من حال هؤلاء المشركين."],[589,"§الانشقاق\nwords\nانشَقَّتتَصَدَّعَت وَتَفَطَّرَت بِالغَمَامِ يَومَ القِيَامَةِ.\nوَأَذِنَت لِرَبِّهَاأَطَاعَت لِأَمرِ رَبِّهَا.\nمُدَّتبُسِطَت، وَوُسِّعَت، وَدُكَّت جِبَالُهَا.\nيَدعُو ثُبُورًايَدعُو بِالهَلاَكِ قَائِلًا: وَاثُبُورَاه!\nلَن يَحُورَلَن يَرجِعَ إِلَى اللهِ لِيُحَاسِبَهُ.\nوَسَقَجَمَعَ.\nاتَّسَقَتَكَامَلَ نُورُهُ وَأَبدَرَ.\nطَبَقًا عَن طَبَقٍأَطوَارًا مُتَعَدِّدَةً، وَأَحوَالًا مُتَبَايِنَةً: نُطفَةً، ثُمَّ عَلَقَةً، وَهَكَذَا.\ndeeds\nاستمع إلى قراءة القرآن بتدبر.\nاسجد سجدة التلاوة عند موضع السجدة من السورة الكريمة.\nاحرص على التيامن في أمورك الطيبة منذ اليوم.\nguid\nبيان بعض أهوال يوم القيامة.\nأذعن لله كما تذعن المخلوقات.\nوعيد المكذبين.\nrefl\nعَلَى ٱلۡأَرَآئِكِ يَنظُرُونَ ٣٥\nأي: إلى ما يشتهون من الجنان والأنهار والحور والولدان؛ ليس لهم شغل غير ذلك وما شابهه من المستلذات. وقال الإمام القشيري: \"أثبت النظر ولم يبين المنظور إليه لاختلافهم: منهم من ينظر إلى قصوره، ومنهم من ينظر إلى حوره، ومنهم ومنهم. والخواص على دوام الأوقات إلى الله تعالى ينظرون، كما أن الفجار دائمًا عن ربهم محجوبون\". البقاعي: ٢١/٣٢٧.\nلماذا أخبر عن نظر المؤمنين في الجنة ولم يتكلم عن المنظور إليه؟\nيَٰٓأَيُّهَا ٱلۡإِنسَٰنُ إِنَّكَ كَادِحٌ إِلَىٰ رَبِّكَ كَدۡحٗا فَمُلَٰقِيهِ ٦\nحثٌّ على الاجتهاد في الإحسان في العمل؛ لأن من أيقن بأنه لا بد له من العرض على الملك أفرغ جهده في العمل بما يحمده عليه عند لقائه. البقاعي: ٢١/٣٣٩.\nما الواجب على العبد فعله إذا علم أنه ملاقٍ ربه -عز وجل-؟\nوَيَنقَلِبُ إِلَىٰٓ أَهۡلِهِۦ مَسۡرُورٗا ٩\nفإنه كان في الدنيا في أهله مشفقًا من العرض على الله، مغمومًا مضرورًا، يحاسب نفسه بكرة وعشيًا حسابًا عسيرًا، مع ما هو فيه من نكد الأهل وضيق العيش وشرور المخالفين. البقاعي: ٢١/٣٤١.\nلماذا جوزي المؤمن بالسرور مع أهله في الجنة؟\nوَأَمَّا مَنۡ أُوتِيَ كِتَٰبَهُۥ وَرَآءَ ظَهۡرِهِۦ ١٠\nتمييز الكفرة بكون الإعطاء من وراء ظهورهم؛ ولعل ذلك لأن مؤتي الكتب لا يتحملون مشاهدة وجوههم؛ لكمال بشاعتها أو لغاية بغضهم إياهم، أو لأنهم نبذوا كتاب اللّه وراء ظهورهم. الألوسي: ٣٠/٨١.\nلماذا يُعطى الكافر كتابه من وراء ظهره؟\nإِنَّهُۥ كَانَ فِيٓ أَهۡلِهِۦ مَسۡرُورًا ١٣\nأي: فرِحًا لا يفكر في العواقب، ولا يخاف مما أمامه، فأعقبه ذلك الفرح اليسير الحزن الطويل. ابن كثير: ٤/٤٩٠.\nمتى يكون الفرح مذمومًا؟\nإِنَّهُۥ ظَنَّ أَن لَّن يَحُورَ ١٤\nهذا الظن... مما يشعر أن عدم الإيمان بالبعث، أو الشك فيه هو الدافع لكل سوء والمضيع لكل خير، وأن الإيمان باليوم الآخر هو المنطلق لكل خير والمانع لكل شر. والإيمان بالبعث هو منطلق جميع الأعمال الصالحة كما في مستهل المصحف: ﴿هُدٗى لِّلۡمُتَّقِينَ ...﴾. الشنقيطي: ٨/٤٧١.\nكيف يكون عدم الإيمان بالبعث أو الشك فيه أصل كل شر؟\nبَلَىٰٓۚ إِنَّ رَبَّهُۥ كَانَ بِهِۦ بَصِيرٗا ١٥\nأي: ناظرًا له وعالمًا به أبلغ نظر وأكمل علم؛ فتركه مهملًا مع العلم بأعماله مناف للحكمة والعدل والملك، فهو شيء لا يمكن في العقل بوجه. البقاعي: ٢١/٣٤٥.\nما دلالة الإخبار بإبصار الله للعبد؟"],[590,"§البروج ، الانشقاق\nwords\nغَيرُ مَمنُونٍغَيرُ مُقطُوعٍ وَلاَ مَنقُوصٍ.\nذَاتِ البُرُوجِذَاتِ المَنَازِلِ الَّتِي تَمُرُّ بِهَا الشَّمسُ وَالقَمَرُ.\nوَاليَومِ المَوعُودِهُوَ: يَومُ القِيَامَةِ.\nوَشَاهِدٍ وَمَشهُودٍأَقسَمَ الله بِكُلِّ شَاهِدٍ يَشهَدُ، وَبِكُلِّ مَن يُشهَدُ عَلَيهِ.\nقُتِلَلُعِنَ، وَعُذِّبَ، وَهَلَكَ.\nأَصحَابُ الأُخدُودِالَّذِينَ شَقُّوا فِي الأَرضِ شَقًّا عَظِيمًا؛ لِإِحرَاقِ المُؤمِنِينَ.\nعَذَابُ الـحَرِيقِالعَذَابُ المُحرِقُ.\nالوَدُودُالمُحِبُّ لِأَولِيَائِهِ، المَحبُوبُ لَهُم.\ndeeds\nذكر مسلمًا أو أكثر بالصبر على الأذى في سبيل الله.\nساعد مسلمًا مستضعفًا.\nذكر مسلمًا أو أكثر بأن الله غفور ودود.\nguid\nالاعتبار بأحوال مؤمني الأمم السابقة وما قدموه من تضحية للثبات على الدين.\nانتقام الله تعالى لأوليائه من أعدائه.\nالتوبة من إيذاء المؤمنين.\nrefl\nوَشَاهِدٖ وَمَشۡهُودٖ ٣\nمن المخلوقات ما هو مشهود عليه، ولا يتم نظام العالم إلا بذلك، فكيف يكون المخلوق شاهدًا رقيبًا حفيظًا على غيره، ولا يكون الخالق -تبارك وتعالى- شاهدًا على عباده مطلعًا عليهم رقيبًا. ابن القيم: ٣/٢٧٨.\nما الحكمة من الإخبار بأن الخلق فيهم (شاهد ومشهود)؟\nقُتِلَ أَصۡحَٰبُ ٱلۡأُخۡدُودِ ٤ ٱلنَّارِ ذَاتِ ٱلۡوَقُودِ ٥\nقال علماؤنا: أعلم الله -عز وجل- المؤمنين من هذه الأمة في هذه الآية ما كان يلقاه من وحَّد قبلهم من الشدائد؛ يؤنسهم بذلك، وذكر لهم النبي قصة الغلام ليصبروا على ما يلاقون من الأذى والآلام والمشقات التي كانوا عليها، ليتأسوا بمثل هذا الغلام في صبره وتصلبه في الحق وتمسكه به وبذله نفسه في حق إظهار دعوته ودخول الناس في الدين مع صغر سنه وعظيم صبره. القرطبي: ٢٢/١٩٢-١٩٣.\nلماذا قص الله علينا قصة أصحاب الأخدود؟\nٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدٌ ٩\n﴿ٱلَّذِي لَهُۥ مُلۡكُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۖ﴾: خلقًا وعبيدًا؛ يتصرف فيهم تصرف المالك بملكه، ﴿وَٱللَّهُ عَلَىٰ كُلِّ شَيۡءٍ شَهِيدٌ﴾: علمًا وسمعًا وبصرًا؛ أفلا خاف هؤلاء المتمردون على الله أن يبطش بهم العزيز المقتدر؟! أوَمَا علموا أنهم جميعهم مماليك لله؛ ليس لأحد على أحد سلطة من دون إذن المالك؟! أوَخفي عليهم أن الله محيط بأعمالهم، مجازٍ لهم على فعالهم؟! كلا إن الكافر في غرور، والظالم في جهل وعمى عن سواء السبيل. السعدي: ٩١٨.\nما الحكمة من ذكر الله -سبحانه وتعالى- أن له ملك السموات والأرض بعد ذكر حال الطغاة أصحاب الأخدود؟\nإِنَّ ٱلَّذِينَ فَتَنُواْ ٱلۡمُؤۡمِنِينَ وَٱلۡمُؤۡمِنَٰتِ ثُمَّ لَمۡ يَتُوبُواْ فَلَهُمۡ عَذَابُ جَهَنَّمَ وَلَهُمۡ عَذَابُ ٱلۡحَرِيقِ ١٠\nقال الحسن البصري: \"انظروا إلى هذا الكرم والجود: قتلوا أولياءه وهو يدعوهم إلى التوبة والمغفرة\". ابن كثير: ٤/٤٩٧.\nمن أين يستنبط كرم الله وجوده العظيم من خلال الآية؟\nوَهُوَ ٱلۡغَفُورُ ٱلۡوَدُودُ ١٤\nقالوا: المودة هي المحبة الصافية، وفي هذا سر لطيف؛ حيث قرن الودود بالغفور ليدل ذلك على أن أهل الذنوب إذا تابوا إلى الله وأنابوا غفر لهم ذنوبهم وأحبهم. السعدي: ٩١٩.\nما السر في اقتران اسم الله تعالى (الودود) باسمه (الغفور)؟\nهَلۡ أَتَىٰكَ حَدِيثُ ٱلۡجُنُودِ ١٧ فِرۡعَوۡنَ وَثَمُودَ ١٨\nتسلية له بالإشعار بأنه سيصيب كفرة قومه ما أصاب الجنود... والمعنى: قد أتاك حديثهم وعرفت ما فَعَلُوا وما فُعِل بهم؛ فذكِّر قومك بأيام اللّه تعالى وشؤونه سبحانه، وأنذرهم أن يصيبهم مثل ما أصاب أمثالهم. الألوسي: ٣٠/٣٩.\nفي هذه الآية إنذار ووعيد لكفار قريش، بيِّن ذلك.\nبَلۡ هُوَ قُرۡءَانٞ مَّجِيدٞ ٢١ فِي لَوۡحٖ مَّحۡفُوظِۢ ٢٢\n﴿فِي لَوۡحٍ مَّحۡفُوظِۭ﴾: من التغيير والزيادة والنقص، ومحفوظ من الشياطين؛ وهو اللوح المحفوظ الذي قد أثبت الله فيه كل شيء. وهذا يدل على جلالة القرآن وجزالته، ورفعة قدره عند الله تعالى. السعدي: ٩١٩.\nتحدث عن قدر القرآن الكريم عند الله تعالى من خلال الآيات."],[591,"§الطارق ، الأعلىٰ\nwords\nالثَّاقِبُالمُضِيءُ المُتَوَهِّجُ.\nدَافِقٍمُنصَبٍّ بِسُرعَةٍ فِي الرَّحِمِ.\nالصُّلبِالظَّهرِ.\nوَالتَّرَائِبِعِظَامِ الصَّدرِ.\nتُبلَى السَّرَائِرُتُختَبَرُ وَتُكشَفُ ضَمَائِرُ القُلُوبِ.\nرُوَيدًاقَلِيلًا.\nالمَرعَىالكَلَأَ الأَخضَرَ.\nغُثَاءًهَشِيمًا جَافًّا.\nأَحوَىمُتَغَيِّرًا.\ndeeds\nتذكر ذنبًا فعلته ولم يطلع عليه بَشَرٌ، واستغفر الله منه.\nراجع سورةً أو احفظها.\nأرسل رسالةً تذكر فيها بتقوى الله -عز وجل-.\nguid\nحتى لا تتكبر تذكر أنك خُلقت من نطفة.\nالحذر من كيد الله وإمهاله للمعرضين.\nعلى الإنسان أن يتنبه إلى أعمال قلبه وأعمال الخلوات؛ فالله تعالى يعلم كل شيء.\nrefl\nيَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ٩\nأي: تخرج مخبآتها وتظهر؛ وهو كل ما كان استسره الإنسان من خير أو شر وأضمره من إيمان أو كفر... قال ابن عمر -رضي الله عنهما-: \"يبدي الله يوم القيامة كل سر خفي؛ فيكون زينًا في الوجوه وشينًا في الوجوه\". القرطبي: ٢٢/٢١٢-٢١٤.\nكيف تبلى سرائر العبد يوم القيامة؟\nيَوۡمَ تُبۡلَى ٱلسَّرَآئِرُ ٩\nوفي التعبير عن الأعمال بالسر لطيفة: وهو أن الأعمال نتائج السرائر الباطنة، فمن كانت سريرته صالحة كان عمله صالحًا؛ فتبدو سريرته على وجهه نورًا وإشراقًا وحياء، ومن كانت سريرته فاسدة كان عمله تابعًا لسريرته، لا اعتبار بصورته؛ فتبدو سريرته على وجهه سوادًا وظلمة وشينًا، وإن كان الذي يبدو عليه في الدنيا إنَّما هو عمله لا سريرته؛ فيوم القيامة تبدو عليه سريرته، ويكون الحكم والظهور لها. ابن القيم: ٣/٢٨٨-٢٨٩.\nما أهمية إصلاح السرائر؟\nفَمَا لَهُۥ مِن قُوَّةٖ وَلَا نَاصِرٖ ١٠\nفما للإنسان الكافر يومئذ من قوة يمتنع بها من عذاب الله وأليم نكاله، ولا ناصر ينصره فيستنقذه ممن ناله بمكروه، وقد كان في الدنيا يرجع إلى قوة من عشيرته يمتنع بهم ممن أراده بسوء، وناصر من حليف ينصره على من ظلمه واضطهده. الطبري: ٢٤/٣٥٩.\nوضح وجه نفي القوة والناصر للعبد في القيامة.\nإِنَّهُمۡ يَكِيدُونَ كَيۡدٗا ١٥ وَأَكِيدُ كَيۡدٗا ١٦\nويُعلَمُ بِهذا مَنِ الغالب؛ فإن الآدمي أضعف وأحقر من أن يغالب القوي العليم. السعدي: ٩٢٠.\nيكيد أهل الكفر والضلال للإسلام والمسلمين في كل لحظة؛ فمن الغالب من خلال تدبرك لهذه الآية؟\nوَنُيَسِّرُكَ لِلۡيُسۡرَىٰ ٨\nأي: نسهل عليك أفعال الخير وأقواله، ونشرع لك شرعًا سهلًا سمحًا مستقيمًا عدلًا؛ لا اعوجاج فيه ولا حرج ولا عسر. ابن كثير: ٤/١٠٥.\nاستنبط سماحة الإسلام ويسره من خلال الآية الكريمة.\nفَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ٩\nأي: ذكر حيث تنفع التذكرة، ومن هاهنا يؤخذ الأدب في نشر العلم؛ فلا يضعه عند غير أهله؛ كما قال أمير المؤمنين علي -رضي الله عنه-: \"ما أنت بمحدث قومًا حديثًا لا تبلغه عقولهم إلا كان فتنة لبعضهم\". وقال: \"حدثوا الناس بما يعرفون، أتحبون أن يكذب الله ورسوله؟!\". ابن كثير: ٤/٥٠١.\nدل قوله تعالى ﴿إِن نَّفَعَتِ ٱلذِّكۡرَىٰ﴾ على أدب من آداب طالب العلم؛ فما هو؟\nفَذَكِّرۡ إِن نَّفَعَتِ ٱلذِّكۡرَىٰ ٩ سَيَذَّكَّرُ مَن يَخۡشَىٰ ١٠\nالتذكر التام يستلزم التأثر بما تذكره؛ فإن تذكر محبوبًا طلبه، وإن تذكر مرهوبًا هرب منه. ابن تيمية: ٦/٥٠٢.\nلماذا ربط التذكر بالخشية؟"],[592,"§الأعلىٰ ، الغاشية\nwords\nيَصلَى النَّاريَدخُلُهَا، وَيُقَاسِي حَرَّهَا.\nعَامِلَةٌ نَاصِبَةٌمُجهَدَةٌ بِالعَمَلِ وَالتَّعَبِ فِي النَّارِ.\nآنِيَةٍشَدِيدَةِ الحَرَارَةِ.\nضَرِيعٍنَبتٍ خَبِيثٍ ذِي شَوكٍ، لاَ تَرعَاهُ الدَّوَابُّ.\nلاَغِيَةًلاَ كَلِمَةَ لَغوٍ وَاحِدَةً، وَلاَ نَفسًا تَلغُو وَتَهذِي.\nمَوضُوعَةٌمُعَدَّةٌ لِلشَّارِبِينَ.\nوَنَمَارِقُوَسَائِدُ.\nوَزَرَابِيُّ مَبثُوثَةٌبُسُطٌ كَثِيرَةٌ مَفرُوشَةٌ.\nسُطِحَتبُسِطَت، وَمُهِّدَت.\ndeeds\nقل مثل ما يقول المؤذن، ثم اذكر الدعاء بعد الأذان، ثم اذهب إلى الصلاة مع الجماعة.\nانظر شيئًا تحبه من زينة الدنيا -ولو قليلًا- وتصدق به.\nذكّر مسلمًا بالله.\nguid\nإذا تعارض ما تحب مع ما يحبه الله، فآثر ما يحبه الله.\nالمقصد العظيم من الصلاة إقامة ذكر الله، فاحرص على ذلك.\nليس المهم العمل فقط بل الأهم الإخلاص والقبول.\nrefl\nقَدۡ أَفۡلَحَ مَن تَزَكَّىٰ ١٤ وَذَكَرَ ٱسۡمَ رَبِّهِۦ فَصَلَّىٰ ١٥\nوقدَّم التزكّي على ذكر الله والصلاةِ؛ لأنه أصل العمل بذلك كله؛ فإنه إذا تطهرت النفس أشرقت فيها أنوار الهداية، فعلمت منافعها وأكثرت من الإِقبال عليها. ابن عاشور: ٣٠/٢٨٨.\nلماذا قدم التزكي على ذكر الله والصلاة؟\nبَلۡ تُؤۡثِرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا ١٦\nالمراد بإيثار الحياة الدنيا هو الرضاء والاطمئنان بها، والإعراض عن الآخرة بالكلية. الألوسي: ١٥/٣٢٢.\nما المراد بإيثار الحياة الدنيا؟\nوُجُوهٞ يَوۡمَئِذٍ خَٰشِعَةٌ ٢ عَامِلَةٞ نَّاصِبَةٞ ٣\n(خاشعة): ذليلة. ولم توصف بالذل ابتداء لما في وصفها بالخشوع من الإشارة إلى التهكم وأنها لم تخشع في وقت ينفع فيه الخشوع، وكذا حال وصفها بالعمل في قوله سبحانه عاملة ناصبة. الألوسي: ١٥/٣٢٥.\nما المقصود من وصف وجوه العصاة يوم القيامة بأنها خاشعة وعاملة؟\nفِي جَنَّةٍ عَالِيَةٖ ١٠\nووصف الجنة بــ(عالية) لزيادة الحسن؛ لأن أحسن الجنات ما كان في المرتفعات. ابن عاشور: ٣٠/٢٩٩.\nلماذا وصفت الجنة بأنها عالية؟\nلَّا تَسۡمَعُ فِيهَا لَٰغِيَةٗ ١١\nبل المسموع فيها الذكر من: التحميد والتمجيد والتنزيه؛ لحمل ما يرى فيها من البدائع على ذلك، مع نزع الحظوظ الحاملة على غيره من القلوب بما كانوا يكرهون من لغو أهل الدنيا المنافي للحكمة. البقاعي: ٢٢/٩.\nما البديل في الجنة عن لغو الدنيا؟\nفِيهَا سُرُرٞ مَّرۡفُوعَةٞ ١٣\nوقوله: ﴿فِيهَا سُرُرٌ مَّرۡفُوعَةٌ﴾: والسرر: جمع سرير، (مرفوعة) ليرى المؤمن إذا جلس عليها جميع ما خوَّله ربه من النعيم والملك فيها، ويلحق جميع ذلك بصره. الطبري: ٢٤/٣٨٧.\nلماذا جعل الله تعالى سرر الجنة مرفوعة؟\nأَفَلَا يَنظُرُونَ إِلَى ٱلۡإِبِلِ كَيۡفَ خُلِقَتۡ ١٧\nحض على النظر في خلقتها لما فيها من العجائب: في قوتها وانقيادها مع ذلك لكل ضعيف، وصبرها على العطش، وكثرة المنافع التي فيها من الركوب والحمل عليها، وأكل لحومها وشرب ألبانها وأبوالها وغير ذلك. ابن جزي: ٢/٥٦٦.\nاذكر بعض العجائب في خلق الإبل."],[593,"§الفجر ، الغاشية\nwords\nإِيَابَهُممَرجِعَهُم بَعدَ المَوتِ.\nلِذِي حِجرٍلِصَاحِبِ عَقلٍ.\nإِرَمَقَبِيلَةِ إِرَمَ؛ نِسبَةً إِلَى جَدِّهِم.\nذَاتِ العِمَادِصَاحِبَةِ القُوَّةِ وَالأَبنِيَةِ المَرفُوعَةِ عَلَى الأعمِدَةِ.\nجَابُواقَطَعُوا.\nذِي الأَوتَادِصَاحِبِ الجُنُودِ الَّذِينَ ثَبَّتُوا مُلكَهُ.\nفَقَدَرَضَيَّقَ.\nولاَ تَحَآضُّونَلاَ يَحُثُّ بَعضُكُم بَعضًا.\nالتُّرَاثَالمِيرَاثَ.\nجَمًّامُفرِطًا.\ndeeds\nصَلِّ الوتر.\nأكرم يتيمًا بهدية أو كلمة طيبة.\nتصدق بمال يخفف حبه في قلبك.\nguid\nفضل العشر من ذي الحجة.\nالرضا بقضاء الله وقدره من صفات المؤمنين.\nأكرم الأيتام والمساكين.\nrefl\nهَلۡ فِي ذَٰلِكَ قَسَمٞ لِّذِي حِجۡرٍ ٥\nأي: لذي عقل ولب ودين وحجى؛ وإنَّما سمي العقل حِجرًا لأنه يمنع الإنسان من تعاطي ما لا يليق به من الأفعال والأقوال. ابن كثير: ٤/٥٠٨.\nما أهمية العقل بالنسبة للمسلم؟\nوَفِرۡعَوۡنَ ذِي ٱلۡأَوۡتَادِ ١٠\nأي الذي ثبّت ملكه تثبيت من يظن أنه لا يزول بالعساكر والجنود، وغيرهم من كل ما يظن أنه يشد أمره، فصارت له اليد المبسوطة في الملك. البقاعي: ٢٢/٣٠.\nما دلالة وصف فرعون بذي الأوتاد ثم إهلاكه؟\nفَصَبَّ عَلَيۡهِمۡ رَبُّكَ سَوۡطَ عَذَابٍ ١٣\nاستعارة السوط للعذاب لأنه يقتضي من التكرار ما لا يقتضيه السيف وغيره؛ قاله ابن عطية. وقال الزمخشري: \"ذكر السوط إشارة إلى عذاب الدنيا؛ إذ هو أهون من عذاب الآخرة، كما أن السوط أهون من القتل\". ابن جزي: ٢/٥٦٩.\nفي استعارة السوط للعذاب في الآية وجهان بلاغيان؛ اذكرهما.\nإِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ ١٤\nقال ابن عباس: \"يسمع ويرى\"، يعني: يرصد خلقه فيما يعملون، ويجازي كلًا بسعيه في الدنيا والأخرى، وسيعرض الخلائق كلهم فيحكم فيهم بعدله، ويقابل كلًا بما يستحقه، وهو المنزه عن الظلم. ابن كثير: ٤/٥١٠.\nما الموقف العملي الذي تتخذه من معرفة رصد الله لجميع الأعمال؟\nفَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ١٥\nصفة الكافر الذي لا يؤمن بالبعث؛ إنَّما الكرامة عنده والهوان بكثرة الحظ في الدنيا وقلَّته، فأما المؤمن فالكرامة عنده أن يكرمه الله بطاعته وتوفيقه المؤدي إلى حظ الآخرة، وإن وسع عليه في الدنيا حمده وشكره. القرطبي: ٢٢/٢٧٦.\nهل كرامة العبد على الله تعالى بنيل حظوظ الدنيا؟\nفَأَمَّا ٱلۡإِنسَٰنُ إِذَا مَا ٱبۡتَلَىٰهُ رَبُّهُۥ فَأَكۡرَمَهُۥ وَنَعَّمَهُۥ فَيَقُولُ رَبِّيٓ أَكۡرَمَنِ ١٥ وَأَمَّآ إِذَا مَا ٱبۡتَلَىٰهُ فَقَدَرَ عَلَيۡهِ رِزۡقَهُۥ فَيَقُولُ رَبِّيٓ أَهَٰنَنِ ١٦ كَلَّاۖ\nيقول تعالى منكرًا على الإنسان في اعتقاده إذا وسع الله تعالى عليه في الرزق ليختبره بذلك فيعتقد أن ذلك من الله إكرام له، وليس كذلك بل هو ابتلاء وامتحان... وكذلك في الجانب الآخر إذا ابتلاه وامتحنه وضيَّق عليه في الرزق يعتقد أن ذلك من الله إهانة له؛ كما قال الله تعالى: (كلا) أي: ليس الأمر كما زعم، لا في هذا ولا في هذا؛ فإن الله تعالى يعطي المال من يحب ومن لا يحب، ويضيق على من يحب ومن لا يحب، وإنَّما المدار في ذلك على طاعة الله في كل من الحالين: إذا كان غنيًا بأن يشكر الله على ذلك، وإذا كان فقيرًا بأن يصبر. ابن كثير: ٤/٥١٠.\nالغنى والفقر قد يكونان نعمتين، وقد يكونان نقمتين؛ بيِّن ذلك من خلال الآيات.\nوَلَا تَحَٰٓضُّونَ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ ١٨\nأي: لا يحض بعضكم بعضًا على طعام المحاويج من المساكين والفقراء؛ وذلك لأجل الشح على الدنيا ومحبتها الشديدة المتمكنة من القلوب. السعدي: ٩٢٤.\nما الذي يمنع المرء من إطعام الفقراء والمساكين؟"],[594,"§الفجر ، البلد\nwords\nوَأَنَّى لَهُ الذِّكرَىلاَ يَنفَعُهُ التَّذَكُّرُ؛ فَقَد فَاتَ أَوَانُهُ.\nوَلاَ يُوثِقُلاَ يَشُدُّ بِالسَّلاَسِلِ وَالأَغلاَلِ.\nوَثَاقَهُمِثلَ إِيثَاقِهِ.\nلاَ أُقسِمُأُقسِمُ، وَ(لاَ): لِتَأكِيدِ القَسَمِ.\nكَبَدٍشِدَّةٍ وَعَنَاءٍ مِن مُكَابَدَةِ الدُّنيَا.\nلُبَدًاكَثِيرًا.\nالعَقَبَةَمَشَقَّةَ الآخِرَةِ؛ بِإِنفَاقِ المَالِ، وَالعَمَلِ الصَّالِحِ.\nمَسغَبَةٍمَجَاعَةٍ شَدِيدَةٍ.\nذَا مَترَبَةٍمُعدِمًا لاَ شَيءَ عِندَهُ.\ndeeds\nقل: \"رضيت بالله ربًا، وبالإسلام دينًا، وبمحمد -صلى الله عليه وسلم- نبيًا رسولًا\".\nسَلِ الله حسن الخاتمة.\nأوص بعض من تعرف بالصبر على طاعة الله، أو الصبر عن معصية الله، أو الصبر على أقدار الله، وأوصهم برحمة الخلق.\nguid\nمراقبة الله في السر والعلن.\nفضل مكة وما حباها الله من خصائص.\nعلى العبد مجاهدة نفسه في هذه الدنيا.\nrefl\nيَقُولُ يَٰلَيۡتَنِي قَدَّمۡتُ لِحَيَاتِي ٢٤\nيعني: يندم على كل ما سلف منه من المعاصي إن كان عاصيًا، ويود لو كان ازداد من الطاعات إن كان طائعًا. ابن كثير: ٤/٥١١.\nهل الندم يوم القيامة خاص بالعاصي؟ وضح ذلك.\nيَٰٓأَيَّتُهَا ٱلنَّفۡسُ ٱلۡمُطۡمَئِنَّةُ ٢٧ ٱرۡجِعِيٓ إِلَىٰ رَبِّكِ رَاضِيَةٗ مَّرۡضِيَّةٗ ٢٨\nأي الموقنة يقينًا قد اطمأنت به؛ بحيث لا يتطرق إليها شك في الإيمان، وقيل: المطمئنة التي لا تخاف حينئذ. ابن جزي: ٢/٥٧٢.\nما الصفة التي تستحق النفس بها الرضى؟\nلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِي كَبَدٍ ٤\nالمراد بذلك ما يكابده ويقاسيه من الشدائد في الدنيا وفي البرزخ ويوم يقوم الأشهاد، وأنه ينبغي له أن يسعى في عمل يريحه من هذه الشدائد، ويوجب له الفرح والسرور الدائم؛ وإن لم يفعل فإنه لا يزال يكابد العذاب الشديد أبد الآباد. السعدي: ٩٢٥.\nهل كبد الإنسان وتعبه مقتصر على الحياة الدنيا؟ وكيف يمكن أن ينجي نفسه من هذا الكبد؟\nيَقُولُ أَهۡلَكۡتُ مَالٗا لُّبَدًا ٦\nوسمى الله تعالى الإنفاق في الشهوات والمعاصي إهلاكًا لأنه لا ينتفع المنفق بما أنفق، ولا يعود عليه من إنفاقه إلا الندم والخسار والتعب والقلة. السعدي: ٩٢٥.\nلماذا استخدمت لفظة (أهلكت) بدلًا من \"أنفقت\"؟\nأَلَمۡ نَجۡعَل لَّهُۥ عَيۡنَيۡنِ ٨ وَلِسَانٗا وَشَفَتَيۡنِ ٩ وَهَدَيۡنَٰهُ ٱلنَّجۡدَيۡنِ ١٠\nفهذه المنن الجزيلة تقتضي من العبد أن يقوم بحقوق الله، ويشكر الله على نعمه، وأن لا يستعين بها على معاصيه. السعدي: ٩٢٥.\nإذا علمت أن الله هو الذي خلق عينيك ولسانك وشفتيك، وهو الذي بين لك طريق الخير من طريق الشر؛ فما موقفك العملي من هذه النعم؟\nفَلَا ٱقۡتَحَمَ ٱلۡعَقَبَةَ ١١ وَمَآ أَدۡرَىٰكَ مَا ٱلۡعَقَبَةُ ١٢\nوالعقبة عبارة عن الأعمال الصالحة المذكورة بعد. وجعلها عقبة استعارة من عقبة الجبل؛ لأنها تصعب ويشق صعودها على النفوس. ابن جزي: ٢/٥٧٤.\nما السر في التعبير عن الأعمال الصالحة بــ(العقبة)؟\nيَتِيمٗا ذَا مَقۡرَبَةٍ ١٥\n﴿ذَا مَقۡرَبَةٍ﴾ أي: قرابة، وخُصَّ به لأن الإطعام في حقه أفضل وأولى من غيره. وفيه الحديث أن الصدقة على القريب صدقة وصلة، وعلى البعيد صدقة فقط. الشنقيطي: ٨/٥٣٣.\nلم خص اليتيم القريب بالإطعام؟"],[595,"§الشمس ، الليل ، البلد\nwords\nمُؤصَدَةٌمُطبَقَةٌ مُغلَقَةٌ.\nطَحَاهَابَسَطَهَا.\nدَسَّاهَاأَخفَى نَفسَهُ وَنَقَصَهَا بِالمَعَاصِي.\nفَعَقَرُوهَافَنَحَرُوهَا.\nفَدَمدَمَفَأَطبَقَ عَلَيهِمُ العُقُوبَةَ.\nتَجَلَّىانكَشَفَ بِضِيَائِهِ.\nلَشَتَّىلَمُختَلِفٌ.\ndeeds\nصل ركعتي الضحى.\nقل: \"اللهم آت نفسي تقواها، وزكها أنت خير من زكاها؛ أنت وليها ومولاها\".\nقل: \"اللهم ألهمني رشدي وقني شر نفسي\".\nguid\nشدة عقوبة الله لأهل الكفر المعاندين.\nملازمة تزكية النفس وتأديبها.\nمن أسباب تيسير الأمور: البذل في سبيل الله مع تقوى الله تعالى.\nrefl\nوَنَفۡسٖ وَمَا سَوَّىٰهَا ٧\nالنفس آية كبيرة من آياته التي هي حقيقةٌ بالإقسام بها؛ فإنها في غاية اللطف والخفة، سريعة التنقل والحركة، والتغير والتأثر والانفعالات النفسية -من الهم والإرادة والقصد والحب والبغض-، وهي التي لولاها لكان البدن مجرد تمثال لا فائدة فيه، وتسويتها على هذا الوجه آية من آيات الله العظيمة. السعدي: ٩٢٦.\nيقسم الله بمخلوقاته العظيمة، فما وجه العظمة في النفس التي أقسم بها؟\nفَأَلۡهَمَهَا فُجُورَهَا وَتَقۡوَىٰهَا ٨\nعن محمد بن كعب قال: \"إذا أراد الله -عز وجل- بعبده خيرًا ألهمه الخير فعمل به، وإذا أراد به السوء ألهمه الشر فعمل به\". القرطبي: ٢٢/٣١٢.\nما علامة إرادة الله -سبحانه وتعالى- بعبده الخير أو السوء؟\nقَدۡ أَفۡلَحَ مَن زَكَّىٰهَا ٩ وَقَدۡ خَابَ مَن دَسَّىٰهَا ١٠\nأي لقد فاز بكل مطلوب ونجا من كل مكروه من أنمى نفسه وأعلاها بالتقوى علمًا وعملًا، ولقد خسر من نقصها وأخفاها بالفجور جهلًا وفسوقًا. الألوسي: ١٥/٣٦١.\nكيف تفلح النفس البشرية؟\nفَكَذَّبُوهُ فَعَقَرُوهَا\nأي عقرها الأشقى؛ وأضيف إلى الكل لأنهم رضوا بفعله. القرطبي: ٢٢/٤١٢.\nلماذا أضيف العقر للجميع مع أن الفاعل واحد؟\nوَمَا خَلَقَ ٱلذَّكَرَ وَٱلۡأُنثَىٰٓ ٣\nقسمٌ بخلقه للذكر والأنثى، وكمال حكمته في ذلك أن خلق من كل صنف من الحيوانات التي يريد بقاءها ذكرًا وأنثى ليبقى النوع ولا يضمحل، وقاد كلًا منهما إلى الآخر بسلسلة الشهوة، وجعل كلًا منهما مناسبًا للآخر. السعدي: ٩٢٧.\nما وجه حكمة الله -سبحانه وتعالى- في جعل المخلوقات صنفين؟\nفَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ٥ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ٦ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ٧\nأي نهيئه للطريقة اليسرى؛ وهي فعل الخيرات وترك السيئات. وضد ذلك تيسيره للعسرى، ومنه قوله -صلى الله عليه وسلم-: «اعملوا فكل ميسر لما خلق له» أي: يهيئه الله لما قدر له، ويسهل عليه فعل الخيرات أو الشر. ابن جزي: ٢/٥٨٩.\nبيّن قول النبي -صلى الله عليه وسلم-: «اعملوا فكل ميسر لما خلق له» في ضوء هذه الآية.\nفَأَمَّا مَنۡ أَعۡطَىٰ وَٱتَّقَىٰ ٥ وَصَدَّقَ بِٱلۡحُسۡنَىٰ ٦ فَسَنُيَسِّرُهُۥ لِلۡيُسۡرَىٰ ٧\nقال بعض السلف: \"من ثواب الحسنة: الحسنة بعدها، ومن جزاء السيئة: السيئة بعدها\". ابن كثير: ٤/٥٢٠.\nاشرح الوقفة السابقة في ضوء الآيات المذكورة."],[596,"§الليل ، الضحىٰ\nwords\nلِلعُسرَىلِكُلِّ عُسرٍ وَشَقَاوَةٍ.\nوَمَا يُغنِيلاَ يَنفَعُهُ.\nتَرَدَّىوَقَعَ فِي النَّارِ.\nإِنَّ عَلَينَا لَلهُدَىعَلَينَا أَن نُبَيِّنَ طَرِيقَ الهُدَى؛ فَضلًا مِنَّا وَرَحمَةً.\nتَلَظَّىتَتَوَهَّجُ.\nلاَ يَصلاَهَالاَ يَدخُلُهَا وَيُقَاسِي حَرَّهَا.\nوَسَيُجَنَّبُهَاسَيُبعَدُ عَنهَا.\nسَجَىغَطَّى الكَونَ بِظَلاَمِهِ، وَسَكَنَ.\nوَمَا قَلَىمَا أَبغَضَكَ عِندَمَا أَبطَأَ عَلَيكَ الوَحيَ.\nفَآوَىفَآوَاكَ وَرَعَاكَ.\nعَائِلًافَقِيرًا.\ndeeds\nتصدّق ولو بشيء قليل من مالك.\nصلِّ ركعتي الضحى.\nأكرم يتيمًا.\nguid\nاحرص على تزكية نفسك.\nكثرة المال لا تمنع المكذِّب من العذاب.\nانتظر الثواب من الله ولا تنتظر ثناء من المخلوقين.\nrefl\nٱلَّذِي يُؤۡتِي مَالَهُۥ يَتَزَكَّىٰ ١٨ وَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ١٩\nفي الآية الإرشاد إلى أن صاحب التقوى لا ينبغي له أن يتحمل مَنَّ الخلق ونعمَهم، وإن حمل منهم شيئًا بادر إلى جزائهم عليه؛ لئلَّا يتبقى لأحد من الخلق عليه نعمة تجزى، فيكون بعد ذلك عمله كله لله وحده، ليس للمخلوق جزاء على نعمته. ابن القيم: ٣/٣٢٦.\nما موقف المتقي من إحسان الخلق إليه؟ ولماذا؟\nوَمَا لِأَحَدٍ عِندَهُۥ مِن نِّعۡمَةٖ تُجۡزَىٰٓ ١٩ إِلَّا ٱبۡتِغَآءَ وَجۡهِ رَبِّهِ ٱلۡأَعۡلَىٰ ٢٠ وَلَسَوۡفَ يَرۡضَىٰ ٢١\nأي لا يفعل الخير جزاء على نعمة أنعم بها عليه أحد فيما تقدم، بل يفعله ابتداء خالصًا لوجه الله. ابن جزي: ٢/٥٨٠.\nعلق الله تعالى رضاه عن المنفق في هذه الآية بأمر ما؛ فما هو؟\nمَا وَدَّعَكَ رَبُّكَ وَمَا قَلَىٰ ٣ وَلَلۡأٓخِرَةُ خَيۡرٞ لَّكَ مِنَ ٱلۡأُولَىٰ ٤\nوالحال أن الآخرة خير لك من الأولى وأنت تختارها عليها، ومن حاله كذلك لا يتركه ربه؛ ففيه إرشاد للمؤمنين إلى ما هو مِلاك قرب العبد إلى الرب -عز وجل-، وتوبيخ للمشركين بما هم فيه من التزام أمر الدنيا والإعراض عن الآخرة. الألوسي: ١٥/٣٧٩.\nما صفة العبد القريب من ربه؟ وضح ذلك من خلال الآية.\nوَأَمَّا ٱلسَّآئِلَ فَلَا تَنۡهَرۡ ١٠\nهذا يدخل فيه السائل للمال والسائل للعلم؛ ولهذا كان المعلم مأمورًا بحسن الخلق مع المتعلم، ومباشرته بالإكرام والتحنن عليه؛ فإن في ذلك معونة له على مقصده، وإكرامًا لمن كان يسعى في نفع العباد والبلاد. السعدي: ٩٢٨.\nهل نهر السائل المنهي عنه لسائل المال فقط؟ وضح ذلك.\nوَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ١١\nالتحدث بنعمة الله داع لشكرها، وموجب لتحبيب القلوب إلى من أنعم بها؛ فإن القلوب مجبولة على محبة المحسن. السعدي: ٩٢٩.\nكيف يكون التحدث بنعمة الله سببًا في زيادة الإيمان؟\nوَأَمَّا بِنِعۡمَةِ رَبِّكَ فَحَدِّثۡ ١١\nالتحدث بها شكر لها؛ ولذا استحب بعض السلف التحدث بما عمله من الخير إذا لم يرد به الرياء والافتخار وعلم الاقتداء به. الألوسي: ١٥/٣٨٣.\nلماذا جاء الأمر بالتحدث بنعم الله؟\nأَلَمۡ نَشۡرَحۡ لَكَ صَدۡرَكَ ١\nوإنَّما خص الصدر؛ لأنه محل أحوال النفس من العلوم والإدراكات. والمراد: الامتنان عليه -صلى الله عليه وآله وسلم- بفتح صدره وتوسيعه حتى قام بما قام به من الدعوة، وقدر على ما قدر عليه من حمل أعباء النبوة وحفظ الوحي. الشوكاني: ٥/٤٦١.\nلماذا خص الصدر في الآية الكريمة؟ وما المراد بذلك؟"],[597,"§الشرح ، العلق ، التين\nwords\nأَنقَضَأَثقَلَ.\nفَرَغتَمِن أَشغَالِ الدُّنيَا.\nفَانصَبفَجِدَّ فِي العِبَادَةِ.\nفَارغَبفَتَوَجَّه، وَاطلُب، وَتَضَرَّع.\nوَطُورِ سِينِينَجَبَلِ طُورِ سَينَاءَ الَّذِي كَلَّمَ اللهُ عَلَيهِ مُوسَى -عليه السلام-.\nوَهَذَا البَلَدِمَكَّةَ.\nتَقوِيمٍصُورَةٍ.\nغَيرُ مَمنُونٍغَيرُ مَقطُوعٍ، وَلاَ مَنقُوصٍ.\nعَلَقٍقِطعَةِ دَمٍ غَلِيظٍ.\nالرُّجعَىالرُّجُوعَ وَالمَصِيرَ.\ndeeds\nأشغِل أحد أوقات فراغك بعبادة.\nاقرأ صفحتين من كتاب علم شرعي.\nادع الله أن يعلمك ما ينفعك وأن يزيدك علمًا.\nguid\nالإيمان والعمل الصالح سبب في المحافظة على كرامة العبد عند الله.\nالحرص على التسليم والانقياد لأحكام الدين.\nأهمية القراءة في حياة المسلم.\nrefl\nفَإِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرًا ٥ إِنَّ مَعَ ٱلۡعُسۡرِ يُسۡرٗا ٦\nفالعسر وإن تكرر مرتين، فتكرر بلفظ المعرفة؛ فهو واحد، واليسر تكرر بلفظ النكرة؛ فهو يسران. فالعسر محفوف بيسرين: يسر قبله، ويسر بعده؛ فلن يغلب عسر يسرين. ابن القيم: ٣/٣٣٣.\nاليسر أوسع من العسر وضح ذلك في ضوء هاتين الآيتين.\nلَقَدۡ خَلَقۡنَا ٱلۡإِنسَٰنَ فِيٓ أَحۡسَنِ تَقۡوِيمٖ ٤\nهو اعتداله واستواء شبابه... قال أبو بكر بن طاهر: \"مزينًا بالعقل، مؤديًا للأمر، مهديًا بالتمييز، مديد القامة، يتناول مأكوله بيده\"... أحسن خلق الله باطنًا وظاهرًا: جمال هيئة، وبديع تركيب الرأس بما فيه، والصدر بما جمعه، والبطن بما حواه، والفرج بما طواه، واليدان وما بطشتاه، والرجلان وما احتملتاه. القرطبي:٢٢/٣٦٨-٣٧٠.\nما وجه الامتنان بحسن خلق الإنسان؟ وما مظاهر ذلك فيه؟\nثُمَّ رَدَدۡنَٰهُ أَسۡفَلَ سَٰفِلِينَ ٥\nالمتبادر من السياق الإشارة إلى حال الكافر يوم القيامة، وأنه يكون على أقبح صورة وأبشعها بعد أن كان على أحسن صورة وأبدعها؛ لعدم شكره تلك النعمة. الألوسي: ٣٠/١٧٦.\nمَن المقصود بأنه يُرد أسفل سافلين؟\nأَلَيۡسَ ٱللَّهُ بِأَحۡكَمِ ٱلۡحَٰكِمِينَ ٨\nأي: أما هو أحكم الحاكمين الذي لا يجور ولا يظلم أحدًا؟! ومن عدله أن يقيم القيامة فينتصف للمظلوم في الدنيا ممن ظلمه. ابن كثير: ٤/٥٢٩.\nكيف تدل الآية على البعث والجزاء؟\nٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٣ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ٤\nوخص من التعليمات الكتابة بالقلم لما فيها من تخليد العلوم ومصالح الدين والدنيا. ابن جزي: ٢/٥٩٠.\nما سر تخصيص التعليم بالقلم في الآية؟\nٱقۡرَأۡ وَرَبُّكَ ٱلۡأَكۡرَمُ ٣ ٱلَّذِي عَلَّمَ بِٱلۡقَلَمِ ٤ عَلَّمَ ٱلۡإِنسَٰنَ مَا لَمۡ يَعۡلَمۡ ٥\nمن كرمه تعالى أن علم الإنسان ما لم يعلم؛ فشرفه وكرمه بالعلم، وهو القدر الذي امتاز به أبو البرية آدم على الملائكة. ابن كثير: ٤/٥٣٠.\nما القدر الذي امتاز به آدم وذريته على سائر المخلوقات؟\nكَلَّآ إِنَّ ٱلۡإِنسَٰنَ لَيَطۡغَىٰٓ ٦ أَن رَّءَاهُ ٱسۡتَغۡنَىٰٓ ٧ إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ ٨\nيخبر تعالى عن الإنسان أنه ذو فرح وأشر وبطر وطغيان إذا رأى نفسه قد استغنى وكثر ماله. ثم تهدده وتوعده ووعظه فقال: ﴿إِنَّ إِلَىٰ رَبِّكَ ٱلرُّجۡعَىٰٓ﴾ أي: إلى الله المصير والمرجع، وسيحاسبك على مالك؛ من أين جمعته؟ وفيم صرفته؟ ابن كثير: ٤/٥٣١.\nما الواجب على الإنسان في حال غناه؟"],[598,"§العلق ، البينة ، القدر\nwords\nلَنَسفَعًالَنَأخُذَنَّهُ أَخذًا عَنِيفًا فَنَطرَحُهُ فِي النَّارِ.\nنَادِيَهُأَهلَ مَجلِسِهِ مِن قَومِهِ وَعَشِيرَتِهِ.\nالزَّبَانِيَةَمَلاَئِكَةَ العَذَابِ.\nمُنفَكِّينَتَارِكِينَ كُفرَهُم.\nكُتُبٌ قَيِّمَةٌأَخبَارٌ صَادِقَةٌ، وَأَوَامِرُ عَادِلَةٌ.\ndeeds\nقل: \"اللهم خذ بناصيتي للبر والتقوى\".\nتقرب إلى الله بسجود عبادة من: شكر أو تلاوة أو صلاة، عند موجبها وسببها.\nذكر من حولك بأهمية الإخلاص في العبادة.\nguid\nفضل ليلة القدر وما فيها من الخيرات.\nالحرص على الاجتماع على كتاب الله وسنة رسوله ونبذ الافتراق.\nمن أفضل الأعمال بعد التوحيد: الصلاة التي هي حق لله، والزكاة التي هي حق الخلق.\nrefl\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ١\nكون إنزال القرآن هنا في الليل دون النهار مشعر بفضل اختصاص الليل. وقد أشار القرآن والسنة إلى نظائره؛ فمن القرآن قوله تعالى: ﴿سُبۡحَٰنَ ٱلَّذِيٓ أَسۡرَىٰ بِعَبۡدِهِۦ لَيۡلٗا﴾ [الإسراء: ١]، ومنه قوله: ﴿وَمِنَ ٱلَّيۡلِ فَتَهَجَّدۡ بِهِۦ نَافِلَةً لَّكَ﴾ [الإسراء: ٧٩]، ﴿وَمِنَ ٱلَّيۡلِ فَسَبِّحۡهُ وَأَدۡبَٰرَ ٱلسُّجُودِ﴾ [ق: ٤٠]، ﴿إِنَّ نَاشِئَةَ ٱلَّيۡلِ هِيَ أَشَدُّ وَطۡـٔٗا وَأَقۡوَمُ قِيلًا﴾ [المزمل: ٦]، وقوله: ﴿كَانُواْ قَلِيلٗا مِّنَ ٱلَّيۡلِ مَا يَهۡجَعُونَ﴾ [الذاريات: ١٧]. ومن السنة قوله: «إذا كان ثلث الليل الآخر ينزل ربنا إلى سماء الدنيا...» الحديث. وهذا يدل على أن الليل أخص بالنفحات الإلهية، وبتجليات الرب سبحانه لعباده؛ وذلك لخلو القلب وانقطاع الشواغل وسكون الليل، ورهبته أقوى على استحضار القلب وصفائه. الشنقيطي: ٩/٣٨.\nبيّن سبب ذكر إنزال القرآن هنا في الليل دون النهار.\nإِنَّآ أَنزَلۡنَٰهُ فِي لَيۡلَةِ ٱلۡقَدۡرِ ١\nالضمير في أنزلناه للقرآن؛ دل على ذلك سياق الكلام، وفي ذلك تعظيم للقرآن من ثلاثة أوجه: أحدها: أنه ذكر ضميره دون اسمه الظاهر؛ دلالة على شهرته والاستغناء عن تسميته. الثاني: أنه اختار لإنزاله أفضل الأوقات. والثالث: أن الله أسند إنزاله إلى نفسه. ابن جزي: ٢/٥٩٣.\nدلت الآية على تعظيم القرآن من عدة أوجه، بيّنها.\nلَمۡ يَكُنِ ٱلَّذِينَ كَفَرُواْ مِنۡ أَهۡلِ ٱلۡكِتَٰبِ وَٱلۡمُشۡرِكِينَ مُنفَكِّينَ حَتَّىٰ تَأۡتِيَهُمُ ٱلۡبَيِّنَةُ ١\nدل ذلك على غاية العوج لأهل الكتاب؛ لأنهم كانوا لما عندهم من العلم أولى من المشركين بالاجتماع على الهدى، ودل ذلك على أن وقوع اللَّدَد والعناد من العالِم أكثر. البقاعي: ٢٢/١٩٢.\nلماذا قدم أهل الكتاب على المشركين في اللوم؟\nوَمَا تَفَرَّقَ ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ إِلَّا مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَةُ ٤\nوإنَّما خص الذين أوتوا الكتاب بالذكر هنا بعد ذكرهم مع غيرهم في أول السورة؛ لأنهم كانوا يعلمون صحة نبوّة سيدنا محمد -صلى الله عليه وسلم- بما يجدون في كتبهم من ذكره. ابن جزي: ٢/٥٩٧.\nلِمَ خصّ الله أهل الكتاب بالذكر في هذه الآية، مع أنه ذكرهم في بداية السورة مع غيرهم؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ٥\n﴿وَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ﴾ أي: متحنفين عن الشرك إلى التوحيد. (ويقيموا الصلاة) وهي أشرف عبادات البدن، (ويؤتوا الزكاة) وهي الإحسان إلى الفقراء والمحاويج. ﴿وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ﴾ أي: الملة القائمة العادلة، أو الأمة المستقيمة المعتدلة. وقد استدل كثير من الأئمة -كالزهري والشافعي- بهذه الآية الكريمة على أن الأعمال داخلة في الإيمان. ابن كثير: ٤/٥٤٠.\nكيف تدل الآية على مذهب أهل السنة والجماعة في أن الإيمان: تصديق بالجنان، وقول باللسان، وعمل بالأركان؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ وَيُقِيمُواْ ٱلصَّلَوٰةَ وَيُؤۡتُواْ ٱلزَّكَوٰةَۚ وَذَٰلِكَ دِينُ ٱلۡقَيِّمَةِ ٥\nوخص الصلاة والزكاة بالذكر مع أنهما داخلان في قوله: ﴿لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ﴾ لفضلهما وشرفهما، وكونهما العبادتين اللتين من قام بهما قام بجميع شرائع الدين. السعدي: ٩٣٢.\nلماذا خص الصلاة والذكر مع أنهما داخلتان في العبادة؟\nوَمَآ أُمِرُوٓاْ إِلَّا لِيَعۡبُدُواْ ٱللَّهَ مُخۡلِصِينَ لَهُ ٱلدِّينَ حُنَفَآءَ\nوفي هذا دليل على وجوب النية في العبادات؛ فإن الإخلاص من عمل القلب؛ وهو أن يراد به وجه الله تعالى لا غيره. القرطبي: ٢٢/٤١٢.\nما الأصل العظيم الذي تدل عليه الآية؟"],[599,"§الزلزلة ، البينة ، العاديات\nwords\nيَصدُرُ النَّاسُيَرجِعُونَ عَن مَوقِفِ الحِسَابِ.\nأَشتَاتًاأَصنافًا مُتَفَرِّقِينَ.\nوَالعَادِيَاتِ ضَبحًاقَسَمٌ بِالخَيلِ الجَارِيَةِ فِي سَبِيلِ اللهِ، حِينَ يَظهَرُ صَوتُهَا مِن سُرعَةِ عَدوِهَا.\nفَالمُورِيَاتِ قَدحًافَالمُوقِدَاتِ بِحَوَافِرِهَا النَّارَ مِن شِدَّةِ عَدوِهَا.\nفَالمُغِيرَاتِ صُبحًافَالخَيلِ الَّتِي تُغِيرُ وَتُبَاغِتُ العَدُوَّ صَبَاحًا.\nفَأَثَرنَفَهَيَّجنَ.\nنَقعًاغُبَارًا.\nفَوَسَطنَ بِهِ جَمعًافَتَوَسَّطنَ بِرُكبَانِهِنَّ جُمُوعَ الأَعدَاءِ.\ndeeds\nصلِّ ركعتين في مكان تحب أن يشهد لك يوم القيامة.\nحاسب نفسك هذه الليلة على ما عملت من خير وشر.\nتبسم في وجه أخيك المسلم، وأمط الأذى عن طريق الناس؛ فإن هذه الأعمال لا تكلف شيئًا وأجرها كبير.\nguid\nأهل الإيمان والعمل الصالح هم خير الخليقة.\nشدة أهوال يوم القيامة.\nالأصل في الموت المفاجأة.\nrefl\nرَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ\nلأنهم لم يبق لهم أمنية إلا أعطاهموها، مع علمهم أنه متفضل في جميع ذلك، لا يجب عليه لأحد شيء، ولا يقدره أحد حق قدره؛ فلو أخذ الخلق بما يستحقونه أهلكهم. وأعظم نعمه عليهم ما منّ عليهم به من متابعتهم رسول الله؛ فإن ذلك كان سببًا لكل خير. البقاعي: ٢٢/١٩٨.\nما دلالة قوله: ﴿وَرَضُواْ عَنۡهُۚ﴾؟\nجَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ٨\nالخشية ملاك السعادة الحقيقية والفوز بالمراتب العلية؛ إذ لولاها لم تُترك المناهي والمعاصي، ولا استُعِد ليوم يؤخذ فيه بالأقدام والنواصي. الألوسي: ١٥/٤٣١.\nما معنى الخشية؟\nجَزَآؤُهُمۡ عِندَ رَبِّهِمۡ جَنَّٰتُ عَدۡنٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ رَّضِيَ ٱللَّهُ عَنۡهُمۡ وَرَضُواْ عَنۡهُۚ ذَٰلِكَ لِمَنۡ خَشِيَ رَبَّهُۥ ٨\nفمن خاف ربه هذا الخوف انفك من جميع ما عنده مما لا يليق بجنابه سبحانه، ولم يقدح في البينة ولا توقف فيها، وما فارق الخوف قلبًا إلا خرب. البقاعي: ٢٢/١٩٩.\nما علامة خشية العبد من ربه؟\nيَوۡمَئِذٖ تُحَدِّثُ أَخۡبَارَهَا ٤\nتشهد على العاملين بما عملوا على ظهرها من خير وشر؛ فإن الأرض من جملة الشهود الذين يشهدون على العباد بأعمالهم. السعدي: ٩٣٢.\nما السلوك العملي الذي تستفيده من هذه الآية؟\nيَوْمَىِٕذٍ يَّصْدُرُ النَّاسُ اَشْتَاتًا لِّيُرَوْا اَعْمَالَهُمْۗ ٦\nما من أحد يوم القيامة إلا ويلوم نفسه؛ فإن كان محسنًا فيقول: لم لا ازددت إحسانًا؟! وإن كان غير ذلك يقول: لم لا نزعت عن المعاصي؟! وهذا عند معاينة الثواب والعقاب. وكان ابن عباس يقول: أشتاتا: \"متفرقين على قدر أعمالهم\". القرطبي: ٢٢/٤٣٧.\nما الحكمة من رؤية الناس أعمالهم في هذا الموقف؟\nفَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ٧ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ٨\nالمثقال هو الوزن، والذرة هي النملة الصغيرة، والرؤية هنا ليست برؤية بصر، وإنَّما هي عبارة عن الجزاء. وذكر الله مثقال الذرة تنبيهًا على ما هو أكثر منه من طريق الأولى؛ كأنه قال: من يعمل قليلًا أو كثيرًا. ابن جزي: ٢/٦٠٠.\nعلى أي شيء يدل ذكر مثقال الذرة في الآية؟\nفَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ٧ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ ٨\nعن أنس، أن رسول الله قال: «إن الله لا يظلم المؤمن حسنة؛ يثاب عليها الرزق في الدنيا، ويجزى بها في الآخرة. وأمَّا الكافر؛ فيعطيه بها في الدنيا، فإذا كان يوم القيامة لم تكن له حسنة». الطبري: ٢٤/٥٥٣.\nإن الله عدل لا يظلم أحدًا، ومع ذلك الكافر لا يجد يوم القيامة الخير الذي عمله في الدنيا؛ كيف ذلك؟"],[600,"§العاديات ، القارعة ، التكاثر\nwords\nلَكَنُودٌلَجَحُودٌ.\nلَشَهِيدٌلَمُقِرٌّ عَلَى جُحُودِهِ.\nالخَيرِالمَالِ.\nبُعثِرَأُثِيرَ، وَأُخرِجَ.\nالمَبثُوثِالمُنتَشِرِ.\nكَالعِهنِكَالصُّوفِ المَصبُوغِ بِأَلوَانٍ مُختَلِفَةٍ.\nالمَنفُوشِالَّذِي مُزِّقَ، وَنُفِشَ، فَتَفَرَّقَت أَجزَاؤُهُ.\nفَأُمُّهُ هَاوِيَةٌمَأوَاهُ إِلَى جَهَنَّمَ يَهوِي عَلَى رَأسِهِ.\nعِلمَ اليَقِينِحَقَّ العِلمِ.\nعَينَ اليَقِينِلَتُبصِرُنَّ جَهَنَّمَ يَقِينًا بِلاَ رَيبٍ.\ndeeds\nتصدق بشيء تحبه.\nثقِّل موازينك بعدة أعمال صالحة تقوم بها هذا اليوم.\nاذهب لزيارة المقابر؛ فإنها تذكر الآخرة.\nguid\nاحذر أن تجحد نعمة أنعمها الله عليك.\nالعناية بأعمال القلوب.\nعلى العبد ألا تشغله الدنيا عن الدين.\nrefl\nإِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٞ ٦\n﴿إِنَّ ٱلۡإِنسَٰنَ لِرَبِّهِۦ لَكَنُودٌ﴾ أي: لكفور جحود؛ مِن: كند النعمة: كفرها ولم يشكرها... المراد به كل الناس على معنى أن طبع الإنسان يحمله على ذلك؛ إلا إذا عصمه الله تعالى بلطفه وتوفيقه. الألوسي: ١٥/٤٤٥.\nما موقفك بعد أن علمت أن أكثر الناس لا يشكرون الله سبحانه؟\nوَإِنَّهُۥ لِحُبِّ ٱلۡخَيۡرِ لَشَدِيدٌ ٨\nأي: كثير الحب للمال، وحبه ذلك هو الذي أوجب له ترك الحقوق الواجبة عليه؛ قدم شهوة نفسه على حق ربه. كل هذا لأنه قصر نظره على هذه الدار، وغفل عن الآخرة. السعدي: ٩٣٣.\nما تأثير شدة حب الإنسان للمال على سلوكه الأخلاقي؟\n۞أَفَلَا يَعۡلَمُ إِذَا بُعۡثِرَ مَا فِي ٱلۡقُبُورِ ٩ وَحُصِّلَ مَا فِي ٱلصُّدُورِ ١٠\nوجمع سبحانه بين القبور والصدور... فإن الإنسان يواري صدرُه ما فيه من الخير والشر، ويواري قبرُه جسمَه؛ فيخرج الرب جسمه من قبره، وسره من صدره؛ فيصير جسمه بارزًا على الأرض، وسره باديًا على وجهه. ابن القيم: ٣/٣٥٢-٣٥٣.\nلماذا جمع بين الصدور والقبور في سياق واحد؟\nأَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ١\nهذا خبر يراد به الوعظ والتوبيخ، ومعنى (ألهاكم): شغلكم، و(التكاثر): المباهاة بكثرة المال والأولاد، وأن يقول هؤلاء: نحن أكثر، ويقول هؤلاء: نحن أكثر. ولما قرأها النبي قال: «يقول ابن آدم: مالي مالي. وليس لك من مالك إلا ما أكلت فأفنيت، أو لبست فأبليت، أو تصدقت فأمضيت». ابن جزي: ٢/٦٠٥.\nما المراد بهذا الخبر؟ مع ذكر بعض صور التكاثر.\nأَلۡهَىٰكُمُ ٱلتَّكَاثُرُ ١\nولم يذكر المتكاثر به؛ ليشمل ذلك كل ما يتكاثر به المتكاثرون، ويفتخر به المفتخرون من: التكاثر في الأموال، والأولاد، والأنصار، والجنود، والخدم، والجاه، وغير ذلك مما يقصد به مكاثرة كل واحد للآخر، وليس المقصود به الإخلاص لله تعالى. السعدي: ٩٣٣.\nلماذا لم يذكر المتكاثر به؟\nحَتَّىٰ زُرۡتُمُ ٱلۡمَقَابِرَ ٢\nعن قتادة قال: \"كانوا يقولون: نحن أكثر من بني فلان، ونحن أعد من بني فلان، وهم كل يوم يتساقطون إلى آخرهم، والله مازالوا كذلك حتى صاروا من أهل القبور كلهم\". القرطبي: ٢٢/ ٤٤٩-٤٥٠.\nما نهاية تفاخر بني آدم؟\nثُمَّ لَتُسۡـَٔلُنَّ يَوۡمَئِذٍ عَنِ ٱلنَّعِيمِ ٨\nأي: عن شكر النعيم؛ فيطالب العبد بأداء شكر نعمة الله على النعيم. ابن تيمية: ٧/١٧٨.\nكيف يسلم العبد من المحاسبة على النعم؟"]])